window.PLATFORM_DATA = {"courseTitle": "المستوى الأول: فهم عمل الأداة بكل تفاصيلها", "courseSub": "تدريب المختصين الشركاء على أداة البروفيل الحسي", "lessons": [{"n": 1, "title": "جولة في الأداة: من الدخول إلى الخطة", "intro": "<p>في نهاية هذا الدرس تستطيع أن تتنقل داخل أداة أوسع للبروفيل الحسي بثقة: تعرف أقسام واجهتها، وتختار الفئة العمرية الصحيحة، وتدخل بالكود الصحيح، وتفهم ما يحدث من لحظة إكمال الاستبيان حتى وصول التقرير وبدء الخطة. هذا الدرس عن «كيف تعمل الأداة» — أما قراءة النتائج وتفسيرها فهي موضوع المستوى الثاني، وبناء الخطة ومتابعتها موضوع المستوى الثالث.</p>", "slides": [{"kind": "cover", "title": "المستوى الأول: فهم عمل الأداة بكل تفاصيلها", "sub": "الدرس 1: جولة في الأداة — من الدخول إلى الخطة", "goals": ["تتنقل في واجهة الأداة وتعرف وظيفة كل قسم فيها", "تختار الفئة العمرية الصحيحة لكل حالة", "تفرّق بين كود التقييم وكود الخطة وتدير أكواد عيادتك", "تصف للأسرة ما سيحدث من الإرسال حتى التقرير والخطة"]}, {"kind": "slide", "title": "الواجهة الرئيسية — خريطة الأداة", "img": "a1-home.png", "points": ["شريط هدية اليوم: مجال حسي كامل يفتح مجانًا كل يوم للجميع — نافذة التعرف على الأداة، لا الأداة كاملة.", "زر «جرّب مجانًا — مجال اليوم»: ينقلك مباشرة إلى صفحة مجال اليوم.", "مدخل المشتركين: «ابدأ التقييم الآن» لحامل كود التقييم، و«ادخل الخطة» لحامل كود الخطة.", "الأداة في أرقام: 9 مجالات حسية، 12 شهرًا من الأنشطة، 3 فئات عمرية، وإشراف سريري يتجاوز 30 سنة."], "take": "الخلاصة: الواجهة مرتبة بترتيب رحلة المستخدم نفسه: جرّب ← قيّم ← طبّق الأنشطة.", "check": [], "task": "", "text": {"head": "1) الواجهة الرئيسية", "body": "<p>ادخل إلى sensory.awsaa.ca. الواجهة مرتبة بترتيب رحلة المستخدم نفسه، وكل قسم فيها له وظيفة:</p><ul><li>شريط هدية اليوم في الأعلى: يفتح «مجال اليوم» — مجال واحد من مجالات الأنشطة مفتوح مجانًا ذلك اليوم فقط للزوار. هذه نافذة التعرف على الأداة، ليست الأداة كاملة.</li><li>مدخل المشتركين: زرّان — «ابدأ التقييم الآن» لمن يملك كود تقييم، و«ادخل الخطة» لمن يملك كود خطة نشطًا.</li><li>الفئات العمرية: بطاقات الفئات الثلاث التي يعمل عليها التقييم.</li><li>اختر طريقة الدخول: يعرض مسارات الاشتراك للأفراد (بروفيل وحده، أو اشتراك خطة شهري، أو سنوي). أما مسار العيادات الشريكة فيُدار بعقد الشراكة، لا من هذه الواجهة.</li></ul>"}}, {"kind": "slide", "title": "مساران للدخول ورحلة من 3 خطوات", "img": "a2-paths.png", "points": ["تبويبان منفصلان: «للأولياء» و«للمختصين والعيادات» — مسارك المهني هو الثاني، ولكل مسار خطواته.", "رحلة الحالة في 3 خطوات: أنجز التقييم ← احصل على الكود ← طبّق الأنشطة.", "بطاقات المجالات: أعلى الصفحة تجد المجالات التي تعمل عليها الأداة: اللمس والحركة والحس العميق والانتباه وغيرها."], "take": "الخلاصة: لا يبدأ أي تقييم قبل اختيار المسار الصحيح والفئة العمرية الصحيحة.", "check": [], "task": "", "text": {"head": "2) اختيار الفئة العمرية", "body": "<p>قبل أي تقييم، حدّد الفئة الصحيحة لعمر المتعلم:</p><ul><li>من الولادة إلى 3 سنوات: صيغة مكيّفة لهذا العمر، بنودها موزعة على المجالات التسعة بلغة تناسب الرضّع والصغار.</li><li>من 3 إلى 14 سنة: الصيغة الأساسية — 86 بندًا.</li><li>أكبر من 14 سنة: فئة مجمّدة بقرار المؤسس (2026-10-24) — أُوقف إنتاجها ولا تُقدَّم للأولياء؛ تبقى عند طلب العيادات فقط وبشروط مسبقة. لا تبدأ بها تقييمًا.</li></ul><p>اختيار فئة خاطئة ليس خطأ شكليًا: بنود كل فئة ومعاييرها مصممة لعمرها، وتقييم بالفئة الخاطئة يعطي صورة خاطئة مهما كانت الإجابات دقيقة.</p>"}}, {"kind": "slide", "title": "الفئات العمرية الثلاث", "img": "a3-ages.png", "points": ["أقل من 3 سنوات — «التدخل المبكر»: بنود مكيّفة لعمر الرضّع والصغار، موزعة على المجالات التسعة.", "من 3 إلى 14 سنة — «الفئة الأساسية»: 86 بندًا، وهي صلب عمل الأداة وأكثر فئاتها استعمالًا.", "أكبر من 14 سنة — فئة مجمّدة: أُوقف إنتاجها بقرار المؤسس، ولا تُقدَّم للأولياء؛ تبقى عند طلب العيادات فقط. لا تبدأ بها حالة."], "take": "تنبيه: اختيار فئة خاطئة يعطي صورة خاطئة عن الحالة مهما كانت الإجابات دقيقة — الفئة قرار سريري، لا خطوة إدارية.", "check": [], "task": "", "text": {"head": "3) الدخول بالكود", "body": "<p>الأداة لا تعمل بحسابات وكلمات سر للأسر، بل بأكواد فردية:</p><ul><li>كود التقييم: يفتح استبيانًا واحدًا لحالة واحدة، ويُستهلك بإكماله.</li><li>كود الخطة: يفتح خطة الأنشطة لحالة قيّمت، ويرتبط بمدة اشتراكها.</li></ul><p>الكود شخصي بطبيعته: يُسلَّم لحالة بعينها، ولا توجد أكواد عامة أو رئيسية. عندما تستلم عيادتك دفعة أكواد، كل كود يُسجَّل عندك باسم الحالة التي أخذته — هذه قاعدة تشغيل، لا اقتراح.</p>"}}, {"kind": "slide", "title": "بوابة الدخول: الكود الفردي", "img": "a4-code.png", "points": ["حقل الكود: يُدخل كود التقييم بصيغته الكاملة — وهو يفتح استبيانًا واحدًا لحالة واحدة ثم يُستهلك.", "زر «ابدأ التقييم»: بعد قبول الكود تنفتح بنود الاستبيان مباشرة.", "كود الخطة منفصل عن كود التقييم: الأول للاستبيان، والثاني لفتح أنشطة الخطة بعد صدور التقرير.", "لا توجد أكواد عامة: كل كود تستلمه عيادتك يُسجَّل باسم الحالة التي أخذته."], "take": "الخلاصة: الكود هو عقد الحالة مع الأداة: فردي، مسجّل، وغير قابل للمشاركة.", "check": [], "task": "", "text": {"head": "4) داخل الاستبيان", "body": "<p>بعد قبول الكود تظهر البنود بندًا بندًا، ويجيب عنها من يعرف المتعلم في حياته اليومية (الولي عادة، وبمرافقتك عند الحاجة). قاعدتا الجودة هنا:</p><ul><li>الإجابة عن السلوك المعتاد في الأسابيع الأخيرة، لا عن يوم استثنائي جيد أو سيئ.</li><li>لا إجابات «تجميلية»: البند الذي لا ينطبق يُجاب عنه كما هو؛ الأداة تقرأ الأنماط من مجموع الإجابات الصادقة.</li></ul><p>شريط التقدم يبيّن موقعك في الاستبيان، ويمكن إكماله في جلسة واحدة متصلة.</p>"}}, {"kind": "slide", "title": "مجال اليوم — نافذة الأداة المجانية", "img": "a5-today.png", "points": ["بطاقة المجال المفتوح الآن: في لقطة الدرس يظهر مجال الحاسة الدهليزية — التوازن والحركة والتنسيق الحركي.", "عدّاد الإغلاق: يبقى المجال مفتوحًا حتى منتصف الليل فقط، ثم يأتي مجال اليوم التالي — سبعة مجالات تدور على أيام الأسبوع.", "زر الدخول: ترى أنشطة الأداة الفعلية كما هي، بلا واجهة تجميلية."], "take": "الخلاصة: مجال اليوم أداة تعريف ممتازة للأسرة المترددة — وحدوده واضحة: مجال واحد، ليوم واحد. والانتباه والاجتماعي-العاطفي يبقيان للمشتركين.", "check": [], "task": "", "text": {"head": "5) من الإرسال إلى التقرير", "body": "<p>عند إتمام الاستبيان وإرساله، تُبنى نتائج الحالة مجالًا مجالًا: لكل مجال من المجالات التسعة يُحسب النمط الغالب داخل ذلك المجال، وتُركَّب التوصيات المناسبة له. يصدر التقرير باسم المتعلم وبإحدى ثلاث لغات (العربية أو الإنجليزية أو الفرنسية) حسب اختيار الأسرة، ويمرّ بمراجعة قبل التسليم — ويمكن أن تُرفق به ملاحظة منك كمختص معالج. قراءة هذا التقرير سطرًا سطرًا وتفسيره للأسرة هو صلب المستوى الثاني.</p>"}}, {"kind": "slide", "title": "عيّنة مما ينتظر الحالة داخل الخطة", "img": "a6-activities.png", "points": ["بطاقة نشاط حقيقية: اسم النشاط ومجاله الحسي ونوع التنظيم المستهدف (إشباع، تنظيم، ضبط).", "«+243 نشاطًا آخر داخل الخطة»: ما يظهر في المعاينة جزء يسير من بنك الأنشطة الكامل."], "take": "الخلاصة: الخطة بنك أنشطة مرتب عبر 12 شهرًا، لا نشاط واحد — وإدارتها مع الأسرة هي موضوع المستوى الثالث.", "check": [], "task": "", "text": {"head": "6) الخطة", "body": "<p>التقرير يصف؛ والخطة تتدخل. باشتراك الخطة تتحول نتيجة كل حالة إلى أنشطة يومية مصوّرة من بنك أنشطة أوسع، مرتبة عبر أشهر الاشتراك، تتابعها الأسرة في البيت وتراجعها أنت في عيادتك. وما يراه الزائر في «مجال اليوم» عيّنة صغيرة من عالم هذه الخطة. إدارة الخطة مع الأسرة — بناءً ومتابعة وقياسًا — هي موضوع المستوى الثالث.</p>"}}, {"kind": "slide", "title": "خلاصة الدرس — قائمة تحققك", "img": null, "points": [], "take": "", "check": ["أعرف أقسام الواجهة ووظيفة كل قسم.", "أختار الفئة العمرية الصحيحة قبل أي بدء.", "أفرّق بين كود التقييم وكود الخطة، وأسجّل كل كود باسم حالته.", "أرشد الأسرة إلى قاعدة «السلوك المعتاد» قبل الإجابة.", "أعرف أن التقرير يُراجَع قبل تسليمه، وأن تفسيره مسؤولية المستوى الثاني."], "task": "مهمة عملية قبل الدرس التالي: ادخل إلى sensory.awsaa.ca، وافتح «مجال اليوم»، ثم حدّد بنفسك: أين يبدأ صاحب كود التقييم؟ وأين يدخل صاحب كود الخطة؟ وأين يقع تبويب «للمختصين والعيادات»؟"}], "closing": [{"head": "خلاصة الدرس — قائمة تحققك كمختص شريك", "body": "<p>1. أعرف أقسام الواجهة الأربع ووظيفة كل قسم.</p><p>2. أختار الفئة العمرية الصحيحة قبل أي بدء.</p><p>3. أفرّق بين كود التقييم وكود الخطة، وأسجّل كل كود باسم حالته.</p><p>4. أرشد الأسرة إلى قاعدة «السلوك المعتاد» قبل أن تبدأ الإجابة.</p><p>5. أعرف أن التقرير يُراجَع قبل تسليمه، وأن تفسيره للأسرة مسؤوليتي بمعايير المستوى الثاني.</p>"}, {"head": "قبل أن تنتقل", "body": "<p>جرّب بنفسك: ادخل إلى الأداة، وتصفّح «مجال اليوم»، ثم حدّد على الواجهة أين يبدأ صاحب كود التقييم وأين يدخل صاحب كود الخطة. في الدرس التالي: ما هذه الأداة أصلًا، ولمن تعمل، وموضعها في بوابة أوسع.</p>"}], "scenario": {"q": "أسرة جديدة في عيادتك تسألك قبل أي شيء: من أين نبدأ؟ ما الترتيب الصحيح الذي ترشدها إليه؟", "opts": ["نشتري اشتراك الخطة مباشرة ونبدأ الأنشطة", "نختار الفئة العمرية الصحيحة أولا، ثم ندخل بكود التقييم من مدخل المشتركين", "نفتح مجال اليوم ونعتبر أنشطته تقييما للحالة"], "c": 1, "ex": "لا يبدأ أي تقييم قبل اختيار المسار الصحيح والفئة العمرية الصحيحة، فالفئة الخاطئة تعطي صورة خاطئة مهما دقت الإجابات."}, "quiz": [{"q": "زرا مدخل المشتركين في الواجهة هما:", "opts": ["ابدأ التقييم الآن لحامل كود التقييم، وادخل الخطة لحامل كود الخطة", "سجل حسابا جديدا، واستعد كلمة السر", "اطلب كودا، وادفع الاشتراك"], "c": 0, "ex": "لكل كود بابه: التقييم من بدء التقييم، والخطة من ادخل الخطة."}, {"q": "تعمل الأداة على مجالات حسية عددها، وتمتد أنشطة الخطة عبر:", "opts": ["9 مجالات و12 شهرا", "7 مجالات و6 أشهر", "9 مجالات و3 أشهر"], "c": 0, "ex": "الأداة في أرقام: 9 مجالات، 12 شهرا من الأنشطة، 3 فئات عمرية."}, {"q": "شريط هدية اليوم في أعلى الواجهة هو:", "opts": ["الأداة كاملة مجانا", "خصم على اشتراك الخطة", "نافذة تعرف: مجال واحد يفتح مجانا ذلك اليوم فقط"], "c": 2, "ex": "مجال اليوم نافذة التعرف على الأداة، لا الأداة كاملة."}]}, {"n": 2, "title": "ما أداة البروفيل الحسي؟ موضعها ولمن تعمل", "intro": "<p>في نهاية هذا الدرس تستطيع أن تعرّف أداة أوسع للبروفيل الحسي بجملة دقيقة، وأن تضعها في موضعها الصحيح داخل بوابة أوسع، وأن تميّز لمن تعمل هذه الأداة: الوليّ، والمختص، والعيادة — وما دور كل واحد منهم معها. هذا الدرس يبني «الصورة الكبيرة» التي ستتفرع عنها كل التفاصيل التقنية في الدروس القادمة.</p>", "slides": [{"kind": "cover", "title": "المستوى الأول: فهم عمل الأداة بكل تفاصيلها", "sub": "الدرس 2: ما أداة البروفيل الحسي؟ موضعها في بوابة أوسع ولمن تعمل", "goals": ["تعرّف الأداة بجملة دقيقة واحدة", "تضع الأداة في موضعها داخل بوابة أوسع", "تميّز أدوار الوليّ والمختص والعيادة معها", "تفرّق بين ما تفعله الأداة وما لا تفعله"]}, {"kind": "slide", "title": "تعريف الأداة — قياس ثم تقرير ثم خطة", "img": "11-pricing.png", "points": ["منظومة تقييم وخطة عبر الإنترنت: استبيان بنود يجيب عنه من يعرف المتعلم يوميًا، يصف سلوكه الحسي كما يظهر في حياته العادية.", "تسعة مجالات حسية: الأصوات، اللمس، البصري، الشم والتذوق، الدهليزي، الحس العميق، الحس الداخلي، الانتباه، الاجتماعي-العاطفي.", "المخرج الأول: تقرير باسم المتعلم يصف النمط الغالب في كل مجال مع توصيات.", "المخرج الثاني: عند الاشتراك في الخطة تتحول النتيجة إلى أنشطة يومية مصوّرة تمارسها الأسرة في البيت."], "take": "الخلاصة: الأداة سلسلة كاملة: قياس ← تقرير ← خطة ← متابعة — لا استبيان ينتهي بدرجة.", "check": [], "task": "", "text": {"head": "1) تعريف الأداة", "body": "<p>أداة أوسع للبروفيل الحسي (sensory.awsaa.ca) منظومة تقييم وخطة تعمل عبر الإنترنت:</p><ul><li>تجمع معلومات منظمة عن السلوك الحسي اليومي للمتعلم عبر استبيان بنود يجيب عنه من يعرف المتعلم في حياته اليومية.</li><li>تنظّم النتيجة مجالًا مجالًا عبر تسعة مجالات حسية: الأصوات، واللمس، والبصري، والشم والتذوق، والدهليزي، والحس العميق، والحس الداخلي، والانتباه، والاجتماعي-العاطفي.</li><li>تصدر تقريرًا باسم المتعلم يصف النمط الغالب في كل مجال مع توصيات، ثم تحوّل النتيجة — عند الاشتراك في الخطة — إلى أنشطة يومية مصوّرة تمارسها الأسرة في البيت.</li></ul><p>الأداة إذن ليست استبيانًا ينتهي بدرجة، بل سلسلة كاملة: قياس ← تقرير ← خطة ← متابعة.</p>"}}, {"kind": "slide", "title": "موضعها في بوابة أوسع", "img": "a1-home.png", "points": ["بوابة أوسع (www.awsaa.ca) هي المظلة الأم التي تضم منتجات أوسع كلها.", "مدرسة أوسع المنزلية (school.awsaa.ca): تعليم منزلي منظم من 2 إلى 18 سنة — الباب التعليمي للمنظومة.", "أداة البروفيل الحسي (sensory.awsaa.ca): الباب الحسي — موضوع هذا التدريب.", "سلسلة كتب «حواسي من أوسع»: كتب تطبيقية قصيرة داخل المنظومة."], "take": "الخلاصة: الأداة والمدرسة تتكاملان ولا تتنافسان: واحدة تقيس وتبني الخطة، والأخرى تحمل التعليم اليومي.", "check": [], "task": "", "text": {"head": "2) موضعها في بوابة أوسع", "body": "<p>«بوابة أوسع» (www.awsaa.ca) هي المظلة الأم التي تضم منتجات أوسع كلها، وأهمها:</p><ul><li>مدرسة أوسع المنزلية (school.awsaa.ca): تعليم منزلي منظم لأصحاب طيف التوحد من 2 إلى 18 سنة بمسارات عمرية ودروس يومية.</li><li>أداة البروفيل الحسي وخطة الأنشطة (sensory.awsaa.ca): موضوع هذا التدريب — الباب الحسي للمنظومة.</li><li>سلسلة كتب «حواسي من أوسع»: كتب تطبيقية قصيرة داخل المنظومة.</li></ul><p>الأداة والمدرسة تتكاملان ولا تتنافسان: الأداة تقيس البروفيل الحسي وتبني خطة الأنشطة، والمدرسة تحمل التعليم اليومي. وقد تلتقي الحالة الواحدة عندهما معًا.</p>"}}, {"kind": "slide", "title": "لمن تعمل الأداة؟ ثلاثة أدوار", "img": "a2-paths.png", "points": ["الوليّ: مصدر المعلومات الأول — يجيب عن البنود من معرفته اليومية، وينفّذ الأنشطة في البيت.", "المختص: قارئ التقرير ومفسّره للأسرة، وصاحب قرار دمج النتيجة في برنامج الحالة.", "العيادة: الإطار المنظّم الذي يجمع الحالات ويدير الأكواد والمتابعة بمعايير واحدة.", "وفي الواجهة: تبويب «للأولياء» وتبويب «للمختصين والعيادات» — ومسارك هو الثاني."], "take": "الخلاصة: كل دور واضح ومستقل؛ وخلط الأدوار أول أسباب سوء استعمال الأداة.", "check": [], "task": "", "text": {"head": "3) لمن تعمل الأداة؟", "body": "<ul><li>الوليّ: هو مصدر المعلومات الأول (يجيب عن بنود الاستبيان من معرفته اليومية بالمتعلم)، وهو منفّذ الأنشطة في البيت.</li><li>المختص: هو قارئ التقرير ومفسّره للأسرة، وصاحب قرار كيف تدخل النتائج في برنامج الحالة العلاجي.</li><li>العيادة: هي الإطار المنظّم الذي يجمع الحالات ويدير الأكواد والمتابعة بمعايير واحدة.</li></ul><p>وفي الواجهة ترى هذا التقسيم نفسه: تبويب «للأولياء» وتبويب «للمختصين والعيادات» — مساران منفصلان، ومسارك المهني هو الثاني.</p>"}}, {"kind": "slide", "title": "ماذا تفعل الأداة — وماذا لا تفعل؟", "img": "a6-activities.png", "points": ["تفعل: تنظيم الملاحظة في قياس، ووصف النمط الغالب لكل مجال، واقتراح أنشطة مبنية على النتيجة.", "تفعل: إتاحة إعادة القياس لمقارنة تغيّر البروفيل عبر الزمن.", "لا تفعل: تشخيص التوحد أو أي اضطراب — فهذا خارج نطاقها كليًا.", "لا تفعل: إلغاء التقييم السريري الشامل أو استبدال حكمك المهني."], "take": "الخلاصة: تفصيل الحدود ومتى تُحال الحالة إلى المؤسس — موضوع الدرس 9.", "check": [], "task": "", "text": {"head": "4) ماذا تفعل الأداة وماذا لا تفعل؟", "body": "<p>تفعل الأداة: تنظيم الملاحظة في قياس، ووصف النمط الغالب في كل مجال، واقتراح أنشطة مبنية على النتيجة، وإتاحة إعادة القياس لمقارنة التغيّر عبر الزمن.</p><p>ولا تفعل: تشخيص التوحد أو أي اضطراب، ولا إلغاء التقييم السريري الشامل، ولا استبدال حكمك المهني. تفصيل هذه الحدود — ومتى تُحال الحالة إلى المؤسس إحالة سريرية — هو موضوع الدرس 9.</p>"}}, {"kind": "slide", "title": "خلاصة الدرس — قائمة تحققك", "img": null, "points": [], "take": "", "check": ["أعرّف الأداة بجملة واحدة: قياس عبر تسعة مجالات، يليه تقرير وخطة.", "أعرف موضع الأداة في بوابة أوسع وعلاقتها بالمدرسة.", "أفرّق بين أدوار الوليّ والمختص والعيادة.", "أعرف أن الأداة تصف وتقترح — ولا تشخّص.", "أشرح الصورة لأي أسرة في دقيقتين دون مبالغة."], "task": "مهمة عملية قبل الدرس التالي: اكتب تعريف الأداة كما ستقوله لوليّ يسألك «ما هذه الأداة؟» — ثلاث جمل كحد أقصى، بلا وعود علاجية وبلا مصطلحات لا يفهمها."}], "closing": [{"head": "خلاصة الدرس — قائمة تحققك كمختص شريك", "body": "<p>1. أعرّف الأداة بجملة واحدة: قياس للبروفيل الحسي عبر تسعة مجالات، يليه تقرير وخطة أنشطة.</p><p>2. أعرف موضع الأداة داخل بوابة أوسع وعلاقتها بمدرسة أوسع المنزلية.</p><p>3. أفرّق بين أدوار الوليّ والمختص والعيادة مع الأداة.</p><p>4. أعرف أن الأداة تصف وتنظّم وتقترح — ولا تشخّص.</p><p>5. أستطيع شرح هذه الصورة لأي أسرة في دقيقتين دون مبالغة.</p>"}, {"head": "قبل أن تنتقل", "body": "<p>مهمة عملية: اكتب بخط يدك تعريف الأداة كما ستقوله لوليّ يسألك «ما هذه الأداة؟» — ثلاث جمل كحد أقصى، بلا وعود علاجية وبلا مصطلحات لا يفهمها. في الدرس التالي: الفئات العمرية، ومن يختار ماذا، وكلفة الخطأ في الاختيار.</p>"}], "scenario": {"q": "ولي يسألك بصراحة: هل ستعطينا هذه الأداة تشخيص ابننا؟ ما جوابك المهني؟", "opts": ["نعم، يظهر التشخيص بعد إكمال الاستبيان", "لا: الأداة تقيس البروفيل الحسي وتصدر تقريرا وخطة أنشطة، والتشخيص خارج نطاقها كليا", "نعم إن جاءت النتيجة مرتفعة في مجالات كثيرة"], "c": 1, "ex": "الأداة سلسلة قياس ثم تقرير ثم خطة، ولا تشخص التوحد ولا أي اضطراب."}, "quiz": [{"q": "المخرجان الأساسيان للأداة هما:", "opts": ["درجة ذكاء وحكم تشخيصي", "تقرير يصف النمط الغالب في كل مجال، وخطة أنشطة عند الاشتراك", "وصفة علاجية وتقرير طبي"], "c": 1, "ex": "قياس عبر تسعة مجالات، ثم تقرير، ثم خطة مبنية على النتيجة."}, {"q": "موضع أداة البروفيل الحسي في المنظومة هو:", "opts": ["بديل عن مدرسة أوسع المنزلية", "مشروع مستقل لا علاقة له بأوسع", "منتج داخل بوابة أوسع، إلى جانب المدرسة وسلسلة كتب حواسي من أوسع"], "c": 2, "ex": "بوابة أوسع هي المظلة الأم، والأداة والمدرسة تتكاملان ولا تتنافسان."}, {"q": "دورك كمختص شريك مع الأداة هو:", "opts": ["الإجابة عن البنود بدل الأسرة", "قراءة التقرير وتفسيره للأسرة وقرار دمج النتيجة في برنامج الحالة", "تسليم الأكواد فقط"], "c": 1, "ex": "الولي مصدر المعلومات، والمختص قارئ التقرير ومفسره، والعيادة إطار التنظيم."}]}, {"n": 3, "title": "الفئات العمرية: اختيار يبنى عليه كل شيء", "intro": "<p>في نهاية هذا الدرس تستطيع أن تختار الفئة العمرية الصحيحة لأي حالة بثقة، وأن تشرح الفرق البنيوي بين الفئتين العاملتين في الأداة، وأن تعرف الموقف الرسمي من فئة أكبر من 14 سنة. اختيار الفئة يحدث قبل إدخال الكود وقبل أول بند — وخطؤه لا يُصلحه أي جهد لاحق.</p>", "slides": [{"kind": "cover", "title": "المستوى الأول: فهم عمل الأداة بكل تفاصيلها", "sub": "الدرس 3: الفئات العمرية — بنية كل فئة، ومن يختار ماذا، وكلفة الخطأ", "goals": ["تختار الفئة العمرية الصحيحة لأي حالة بثقة", "تشرح الفرق البنيوي بين الفئتين العاملتين", "تدير الحالات الحدّية بتوثيق ووعي", "تعرف الموقف الرسمي من فئة أكبر من 14 سنة"]}, {"kind": "slide", "title": "الفئتان العاملتان", "img": "12-preview.png", "points": ["من الولادة إلى 3 سنوات — «التدخل المبكر»: بنود مكيّفة بلغة تناسب الرضّع والصغار ومواقفهم اليومية، موزعة على المجالات التسعة.", "من 3 إلى 14 سنة — «الفئة الأساسية»: 86 بندًا، وهي صلب عمل الأداة وأكثر فئاتها استعمالًا.", "لكل فئة بنودها ومعايير قراءتها: البند نفسه قد يعني شيئًا مختلفًا عند رضيع وعند متعلم في العاشرة."], "take": "الخلاصة: لا تُستعمل بنود فئة لعمر فئة أخرى — أبدًا.", "check": [], "task": "", "text": {"head": "1) الفئتان العاملتان", "body": "<ul><li>من الولادة إلى 3 سنوات — «التدخل المبكر»: صيغة مكيّفة لعمر الرضّع والصغار؛ بنودها مكتوبة بلغة تناسب هذا العمر ومواقفه اليومية، وموزعة على المجالات التسعة.</li><li>من 3 إلى 14 سنة — «الفئة الأساسية»: صلب عمل الأداة وأكثر فئاتها استعمالًا — 86 بندًا موزعة على المجالات التسعة.</li></ul><p>لكل فئة بنودها ومعايير قراءتها الخاصة: البند نفسه قد يعني شيئًا مختلفًا عند رضيع وعند متعلم في العاشرة، لذلك لا تُستعمل بنود فئة لعمر فئة أخرى.</p>"}}, {"kind": "slide", "title": "من يختار الفئة؟ قرارك أنت", "img": null, "points": ["الاختيار قرار المختص — لا اختيار الأسرة ولا خطوة آلية في النظام.", "المرجع هو العمر الفعلي يوم بدء التقييم، لا العمر العقلي المقدّر ولا الصف الدراسي.", "الحالات الحدّية: اختر فئة العمر الفعلي، وثبّت الاختيار في ملف الحالة، ولا تبدّله عند إعادة التقييم حتى تبقى المقارنة ممكنة.", "من أكمل فئة تالية أثناء اشتراكه: تبقى خطته على فئته الأصلية حتى إعادة التقييم."], "take": "الخلاصة: ثلاث ثوانٍ من التحقق من تاريخ الولادة قبل البدء توفّر كلفة كل خطأ لاحق.", "check": [], "task": "", "text": {"head": "2) من يختار الفئة؟", "body": "<p>الاختيار قرارك أنت كمختص، لا اختيار الأسرة ولا خطوة آلية:</p><ul><li>المرجع هو عمر المتعلم الفعلي يوم بدء التقييم، لا عمره العقلي المقدّر ولا الصف الدراسي.</li><li>الحالات الحدّية (متعلم قريب جدًا من تمام 3 سنوات أو من تمام 14 سنة): اختر الفئة التي ينتمي إليها عمره الفعلي، وثبّت اختيارك في ملف الحالة، ولا تبدّل الفئة في إعادة التقييم اللاحقة حتى تبقى المقارنة ممكنة.</li><li>إذا أكمل المتعلم سنوات الفئة التالية أثناء اشتراكه، تبقى خطته على فئته الأصلية حتى إعادة التقييم — وهناك يُنظر في الانتقال بوعي وبتوثيق.</li></ul>"}}, {"kind": "slide", "title": "كلفة الخطأ في الاختيار", "img": null, "points": ["صورة خاطئة كاملة: معايير فئة أخرى تقرأ إجابات الحالة، فتخرج نتيجة لا تصفها مهما دقّت الإجابات.", "كود مستهلَك: التقييم الخاطئ يستهلك كود التقييم ولا يعيده.", "خطة فاسدة الأساس: تقرير بفئة خاطئة لا يصلح أساسًا لأي خطة أنشطة."], "take": "تنبيه: خطأ الفئة خطأ لا يُصلحه أي جهد لاحق — الوقاية منه هي كل العلاج.", "check": [], "task": "", "text": {"head": "3) كلفة الخطأ في الاختيار", "body": "<ul><li>تقييم بالفئة الخاطئة يعطي صورة خاطئة مهما كانت الإجابات دقيقة؛ لأن المعايير التي تُقرأ بها الإجابات ليست معايير عمر الحالة.</li><li>الكلفة عملية أيضًا: كود تقييم استُهلك في فئة خاطئة لا يعود، وتقرير بُني على فئة خاطئة لا يصلح أساسًا لخطة.</li><li>القاعدة الوقائية بسيطة: ثلاث ثوانٍ من التحقق من تاريخ الولادة قبل البدء توفّر كل هذا.</li></ul>"}}, {"kind": "slide", "title": "فئة أكبر من 14 سنة — الوضع الرسمي", "img": null, "points": ["مجمّدة بقرار المؤسس (2026-10-24): أُوقف إنتاجها ولا تُقدَّم للأولياء؛ تبقى عند طلب العيادات فقط وبشروط مسبقة.", "عمليًا: لا تبدأ أي تقييم بهذه الفئة، ولا تعرضها على أي أسرة كخيار قائم.", "إن وصلتك حالة فوق 14: سجّل طلبها وارفعه ضمن طلبات العيادات — إعادة فتح الفئة مشروطة بطلب مؤسسي موثّق."], "take": "الخلاصة: قد ترى بطاقتها في الواجهة ضمن تعديلات معلقة — الوضع المعتمد هو ما في هذا الدرس.", "check": [], "task": "", "text": {"head": "4) فئة أكبر من 14 سنة — الوضع الرسمي", "body": "<p>فئة أكبر من 14 سنة مجمّدة بقرار المؤسس (2026-10-24): أُوقف إنتاجها ولا تُقدَّم للأولياء، وتبقى عند طلب العيادات فقط وبشروط مسبقة. عمليًا بالنسبة لك:</p><ul><li>لا تبدأ أي تقييم بهذه الفئة، ولا تعرضها على أي أسرة كخيار قائم.</li><li>إن وصلتك حالة فوق 14 سنة وطلبت الأسرة الخدمة، سجّل الطلب وارفعه ضمن طلبات العيادات — فإعادة فتح الفئة مشروطة بطلب مؤسسي موثّق.</li><li>قد ترى بطاقتها في واجهة الأداة ضمن قائمة تعديلات معلقة — الوضع التدريبي المعتمد هو ما في هذا الدرس.</li></ul>"}}, {"kind": "slide", "title": "خلاصة الدرس — قائمة تحققك", "img": null, "points": [], "take": "", "check": ["أعرف الفئتين العاملتين وبنيتهما (3-14 = 86 بندًا).", "أختار من العمر الفعلي وأوثّق الاختيار.", "لا أبدّل الفئة بين التقييم وإعادة التقييم.", "أتحقق من تاريخ الولادة قبل إدخال أي كود.", "أعرف أن فئة أكبر من 14 مجمّدة — عند طلب العيادات فقط."], "task": "مهمة عملية قبل الدرس التالي: راجع 3 حالات عندك أو افتراضية، وحدّد لكل منها: العمر الفعلي، والفئة الصحيحة، وسبب الاختيار في سطر واحد."}], "closing": [{"head": "خلاصة الدرس — قائمة تحققك كمختص شريك", "body": "<p>1. أعرف الفئتين العاملتين وبنية كل منهما (3-14 = 86 بندًا).</p><p>2. أختار الفئة بنفسي من العمر الفعلي، وأوثّق الاختيار في ملف الحالة.</p><p>3. لا أبدّل الفئة بين التقييم وإعادة التقييم حفاظًا على قابلية المقارنة.</p><p>4. أتحقق من تاريخ الولادة قبل إدخال أي كود.</p><p>5. أعرف أن فئة أكبر من 14 مجمّدة — عند طلب العيادات فقط — فلا أعرضها ولا أبدأ بها.</p>"}, {"head": "قبل أن تنتقل", "body": "<p>مهمة عملية: راجع آخر 3 حالات عندك (أو حالات افتراضية إن كنت في البداية) وحدّد لكل واحدة: العمر الفعلي، والفئة الصحيحة، وسبب الاختيار في سطر واحد. في الدرس التالي: الأكواد الفردية ودورة حياتها.</p>"}], "scenario": {"q": "حالة بدأت اشتراكها في فئة أقل من 3 سنوات، وأكملت عامها الثالث أثناء الاشتراك. ما التصرف الصحيح؟", "opts": ["نبدل فئتها فورا إلى فئة 3 إلى 14", "نعيد التقييم من الصفر الآن", "تبقى خطتها على فئتها الأصلية حتى إعادة التقييم"], "c": 2, "ex": "ثبات الفئة شرط إمكان المقارنة، والتبديل يكون عند إعادة التقييم لا أثناء الخطة."}, "quiz": [{"q": "مرجع اختيار الفئة العمرية هو:", "opts": ["العمر العقلي المقدر", "الصف الدراسي", "العمر الفعلي يوم بدء التقييم"], "c": 2, "ex": "الاختيار قرار المختص، ومرجعه العمر الفعلي لا أي تقدير آخر."}, {"q": "كلفة الخطأ في اختيار الفئة هي:", "opts": ["خطأ شكلي يصحح في أي وقت", "صورة خاطئة كاملة، وكود مستهلك، وخطة فاسدة الأساس", "تأخير يوم واحد في التسليم"], "c": 1, "ex": "خطأ الفئة خطأ لا يصلحه أي جهد لاحق، والوقاية منه هي كل العلاج."}, {"q": "وصلت عيادتك حالة عمرها 16 سنة. موقفك المعتمد:", "opts": ["نبدأ بها تقييما بفئة أكبر من 14", "نقيمها بفئة 3 إلى 14 لأن بنودها أشمل", "لا نقدم الفئة المجمدة، ونسجل الطلب ونرفعه ضمن طلبات العيادات"], "c": 2, "ex": "فئة أكبر من 14 مجمدة بقرار المؤسس، ولا تبقى إلا عند طلب العيادات وبشروط مسبقة."}]}, {"n": 4, "title": "الأكواد الفردية: إدارة رصيد عيادتك", "intro": "<p>في نهاية هذا الدرس تستطيع أن تفرّق بدقة بين كود التقييم وكود الخطة، وأن تدير أكواد عيادتك من لحظة الاستلام إلى الاستهلاك بلا ضياع ولا خلط، وأن تشرح لأي أسرة لماذا لا توجد في منظومة أوسع أكواد عامة أو مشتركة.</p>", "slides": [{"kind": "cover", "title": "المستوى الأول: فهم عمل الأداة بكل تفاصيلها", "sub": "الدرس 4: الأكواد الفردية — أنواعها ودورة حياتها وطلب كود جديد", "goals": ["تفرّق بدقة بين كود التقييم وكود الخطة", "تدير أكواد عيادتك من الاستلام إلى الاستهلاك", "تشرح لماذا لا توجد أكواد عامة", "تطلب كودًا جديدًا بالطريقة المعتمدة"]}, {"kind": "slide", "title": "نوعا الأكواد", "img": "a4-code.png", "points": ["كود التقييم: يفتح استبيانًا واحدًا لحالة واحدة في فئة واحدة، ويُستهلك بإكمال الاستبيان وإرساله.", "كود الخطة: يفتح خطة الأنشطة لحالة قيّمت، ويرتبط بمدة اشتراكها (شهري/سنوي).", "لكل كود بابه: التقييم من شاشة بدء التقييم، والخطة من «ادخل الخطة» أو صفحة الخطة الشهرية."], "take": "الخلاصة: خلط الكودين أكثر أسباب تعثّر الأسر في البداية — وضّح الفرق قبل التسليم لا بعده.", "check": [], "task": "", "text": {"head": "1) نوعا الأكواد", "body": "<ul><li>كود التقييم: يفتح استبيانًا واحدًا لحالة واحدة في فئة عمرية واحدة. يُدخَل في شاشة بدء التقييم، فتنفتح البنود مباشرة. يُستهلك بإكمال الاستبيان وإرساله — فلا يعمل مرة ثانية ولا لحالة أخرى.</li><li>كود الخطة: يفتح خطة الأنشطة لحالة سبق تقييمها، ويرتبط بمدة الاشتراك (شهري أو سنوي). يُدخَل من «ادخل الخطة» في مدخل المشتركين، أو من صفحة الخطة الشهرية عند طلب الكود.</li></ul><p>لا يوجد كود واحد يقوم بالمهمتين؛ خلطهما هو أكثر أسباب تعثّر الأسر في البداية، ودورك أن توضّح الفرق قبل التسليم لا بعده.</p>"}}, {"kind": "slide", "title": "دورة حياة الكود في عيادتك", "img": null, "points": ["1 الاستلام: سجّل الدفعة فورًا في سجل العيادة (الكود، نوعه، تاريخ الاستلام).", "2 التخصيص: عند تسليم كود لحالة اكتب اسمها بجانبه في اللحظة نفسها — كود بلا اسم كود ضائع.", "3 الاستعمال: تابع مع الأسرة إتمام الخطوة حتى نهايتها.", "4 الإغلاق: علّم الكود «مستهلكًا» مع تاريخ الاستهلاك، لتعرف رصيدك الحي دائمًا."], "take": "الخلاصة: إدارة الأكواد سجل ورقي أو رقمي بسيط — لكنه الفرق بين عيادة منظمة ومتابعة ضائعة.", "check": [], "task": "", "text": {"head": "2) دورة حياة الكود", "body": "<p>تمر الأكواد التي تستلمها عيادتك بأربع مراحل، ولكل مرحلة واجب:</p><p>1. الاستلام: تصلك دفعة أكواد؛ سجّلها فورًا في سجل العيادة (الكود، ونوعه، وتاريخ الاستلام).</p><p>2. التخصيص: عند تسليم كود لحالة، اكتب اسم الحالة بجانبه في السجل في اللحظة نفسها — كود بلا اسم في السجل كود ضائع عمليًا.</p><p>3. الاستعمال: تتابع مع الأسرة إتمام الخطوة (إرسال الاستبيان لكود التقييم، أو فتح الخطة لكود الخطة).</p><p>4. الإغلاق: بعد الاستهلاك، علّم الكود «مستهلكًا» في سجلك مع تاريخ الاستهلاك — هكذا تعرف دائمًا رصيدك الحقيقي من الأكواد الحية.</p>"}}, {"kind": "slide", "title": "لماذا لا توجد أكواد عامة؟", "img": null, "points": ["الكود رابط الحالة ببياناتها: التقييم والتقرير والخطة كلها تُبنى على كود بعينه.", "كود مشترك يعني بيانات مختلطة: تقارير قد تصل إلى غير أصحابها — خط أحمر في سرية بيانات الحالات.", "ويعني استحالة التتبّع: من قيّم؟ ومن استلم؟ وماذا بقي من الاشتراك؟"], "take": "الخلاصة: غياب الأكواد العامة قرار سرية وتتبّع مقصود، لا قصور في النظام.", "check": [], "task": "", "text": {"head": "3) لماذا لا توجد أكواد عامة؟", "body": "<p>لأن الكود في هذه المنظومة ليس مفتاح دخول فحسب، بل هو رابط الحالة ببياناتها: التقييم والتقرير والخطة كلها تُبنى على كود بعينه. كود عام أو مشترك يعني:</p><ul><li>بيانات حالات تختلط ببعضها، وتقارير قد تصل إلى غير أصحابها — وهذا خط أحمر في سرية بيانات الحالات.</li><li>استحالة تتبّع من قيّم ومن استلم وماذا بقي من الاشتراك.</li></ul><p>لذلك صُمم النظام بلا أكواد رئيسية وبلا حسابات مشتركة: كل حالة لها كودها، وكل كود له حالة واحدة.</p>"}}, {"kind": "slide", "title": "قواعد تسليم الكود للأسرة", "img": null, "points": ["مكتوبًا دائمًا: رسالة نصية أو ورقة مطبوعة — حرف واحد خاطئ شفهيًا يعني تعثّرًا كاملًا.", "مع الشرح عند التسليم: نوع الكود، وأين يُدخل بالضبط، وماذا سيحدث بعده.", "مع التنبيه: كود التقييم يُستهلك بالإرسال، فلا إغلاق للصفحة قبل إتمام البنود.", "وبلا قنوات عامة: الكود وثيقة حالة شخصية، لا يُرسل في مجموعة مفتوحة."], "take": "الخلاصة: التسليم الجيد يختصر نصف مشاكل الدرس 10 قبل أن تقع.", "check": [], "task": "", "text": {"head": "4) قواعد تسليم الكود للأسرة", "body": "<ul><li>سلّم الكود مكتوبًا بوضوح (رسالة نصية أو ورقة مطبوعة)، لا شفهيًا عبر الهاتف — حرف واحد خاطئ يعني تعثّرًا كاملًا.</li><li>اشرح عند التسليم: هذا كود تقييم أم كود خطة؟ وأين يُدخَل بالضبط؟ وماذا سيحدث بعده؟</li><li>نبّه الأسرة إلى أن كود التقييم يُستهلك بالإرسال، فلا تُغلق الصفحة قبل إتمام البنود (تفصيل إدارة الجلسة في الدرس 5).</li><li>لا ترسل كودًا في مجموعة عامة أو قناة مفتوحة؛ الكود وثيقة حالة شخصية.</li></ul>"}}, {"kind": "slide", "title": "طلب كود جديد — الطريقة المعتمدة", "img": null, "points": ["1 لقطة شاشة توضح موضع الحاجة أو آخر حالة في سجل أكوادك.", "2 وصف مكتوب قصير: نوع الكود المطلوب (تقييم/خطة)، وعدده، واسم الحالة إن كان مخصصًا.", "3 الإرسال إلى ماسنجر صفحة المؤسس — اللقطة والوصف معًا في رسالة واحدة.", "لا طلب شفهيًا ولا وصف بلا لقطة: اللقطة والوصف معًا هما ملف الطلب الذي يُبنى عليه التنفيذ."], "take": "الخلاصة: الطريقة نفسها تنطبق على التبليغ عن خطأ في الدخول أو أي مشكلة أخرى.", "check": [], "task": "", "text": {"head": "5) طلب كود جديد — الطريقة المعتمدة", "body": "<p>عندما تحتاج كودًا جديدًا (نفد رصيدك، أو احتجت كودًا إضافيًا لحالة جديدة)، فالطريقة المعتمدة واحدة ومحددة:</p><p>1. التقط لقطة شاشة توضح موضع الحاجة أو آخر حالة في سجل أكوادك (ما يثبت الطلب ويختصر الشرح).</p><p>2. اكتب وصفًا مكتوبًا قصيرًا: نوع الكود المطلوب (تقييم أم خطة)، وعدده، واسم الحالة إن كان مخصصًا لها.</p><p>3. أرسل اللقطة والوصف معًا إلى ماسنجر صفحة المؤسس — هذه هي قناة التواصل المعتمدة لطلبات الأكواد ولكل تبليغ عن مشكلة في الدخول أو أي مشكلة أخرى.</p><p>لا تُطلب الأكواد باتصال شفهي ولا برسالة وصف بلا لقطة؛ اللقطة والوصف معًا هما «ملف الطلب» الذي يُبنى عليه التنفيذ والتتبّع.</p>"}}, {"kind": "slide", "title": "خلاصة الدرس — قائمة تحققك", "img": null, "points": [], "take": "", "check": ["أفرّق بين كود التقييم وكود الخطة قبل أي تسليم.", "عندي سجل أكواد: الكود، النوع، اسم الحالة، تاريخ الاستهلاك.", "لا كود يخرج بلا اسم حالة بجانبه.", "أسلّم الكود مكتوبًا مع الشرح.", "أطلب الجديد بـ: لقطة + وصف ← ماسنجر صفحة المؤسس."], "task": "مهمة عملية قبل الدرس التالي: أنشئ سجل أكواد عيادتك الآن (الكود، النوع، اسم الحالة، الحالة/التاريخ) ولو كان فارغًا — ستملؤه من أول دفعة."}], "closing": [{"head": "خلاصة الدرس — قائمة تحققك كمختص شريك", "body": "<p>1. أفرّق بين كود التقييم وكود الخطة وأشرح الفرق قبل التسليم.</p><p>2. عندي سجل أكواد للعيادة: الكود ونوعه واسم الحالة وتاريخ الاستهلاك.</p><p>3. لا كود يخرج من عندي بلا اسم حالة مسجّل بجانبه.</p><p>4. أسلّم الكود مكتوبًا مع شرح موضعه وخطوته التالية.</p><p>5. أعرف أن غياب الأكواد العامة قرار سرية وتتبّع، لا قصور في النظام.</p><p>6. أطلب أي كود جديد بالطريقة المعتمدة: لقطة شاشة + وصف مكتوب إلى ماسنجر صفحة المؤسس.</p>"}, {"head": "قبل أن تنتقل", "body": "<p>مهمة عملية: أنشئ سجل أكواد عيادتك الآن (جدول بسيط بالأعمدة الأربعة: الكود، النوع، اسم الحالة، الحالة/التاريخ) ولو كان فارغًا — ستملؤه من أول دفعة. في الدرس التالي: كيف يُكمل الاستبيان بجودة تحمي النتيجة.</p>"}], "scenario": {"q": "سلمت كود تقييم لأسرة شفهيا عبر الهاتف، فتعثرت الأسرة في إدخاله وتعطل بدء التقييم. أين وقع الخلل؟", "opts": ["في منصة الأداة", "في طريقة التسليم: الكود يسلم مكتوبا دائما، مع الشرح والتنبيه", "في قدرة الأسرة"], "c": 1, "ex": "حرف واحد خاطئ شفهيا يعني تعثرا كاملا، والتسليم الجيد يختصر نصف المشاكل قبل أن تقع."}, "quiz": [{"q": "أول ما تفعله عند استلام دفعة أكواد من أوسع هو:", "opts": ["تسجيلها فورا في سجل العيادة: الكود ونوعه وتاريخ الاستلام", "توزيعها على الأسر فورا", "إرسالها في مجموعة العيادة الداخلية"], "c": 0, "ex": "دورة حياة الكود تبدأ بالاستلام المسجل، وكل كود بلا اسم حالة بجانبه كود ضائع."}, {"q": "لا توجد أكواد عامة لأن:", "opts": ["النظام لا يدعمها تقنيا", "الأكواد مكلفة الإنتاج", "الكود المشترك يخلط بيانات الحالات ويجعل التتبع مستحيلا"], "c": 2, "ex": "غياب الأكواد العامة قرار سرية وتتبع مقصود، لا قصور في النظام."}, {"q": "طلب كود جديد يكون بـ:", "opts": ["مكالمة هاتفية للمؤسس", "لقطة شاشة ووصف مكتوب يرسلان إلى ماسنجر صفحة المؤسس", "رسالة صوتية في أي وقت"], "c": 1, "ex": "اللقطة والوصف معا هما ملف الطلب الذي يبنى عليه التنفيذ."}]}, {"n": 5, "title": "إكمال الاستبيان بجودة", "intro": "<p>في نهاية هذا الدرس تستطيع أن تهيّئ أي أسرة لإكمال الاستبيان بجودة تحمي النتيجة: تعرف من يجب أن يجيب، وتشرح قاعدة «السلوك المعتاد» بلغة يفهمها الوليّ، وتتعرّف الأخطاء الخمسة التي تُفسد التقييم قبل أن يبدأ الحساب، فتمنعها مسبقًا بدل أن تكتشفها في التقرير.</p>", "slides": [{"kind": "cover", "title": "المستوى الأول: فهم عمل الأداة بكل تفاصيلها", "sub": "الدرس 5: إكمال الاستبيان بجودة — من يجيب، وقاعدة «السلوك المعتاد»، وأخطاء تُفسد النتيجة", "goals": ["تهيّئ أي أسرة لإكمال الاستبيان بجودة", "تشرح قاعدة «السلوك المعتاد» بلغة الوليّ", "تدير جلسة الإكمال بلا تعب مفسد", "تتعرّف الأخطاء الخمسة وتمنعها مسبقًا"]}, {"kind": "slide", "title": "من يجيب عن البنود؟", "img": "05-assessment-entry.png", "points": ["من يعرف المتعلم يوميًا معرفة مباشرة ومستمرة — الوليّ عادة أو القائم بالرعاية اليومية.", "لا يجيب زائر عابر مهما كانت خبرته؛ فالبنود تصف حياة يومية لا تُرى في جلسة.", "مصدر واحد لوحدة الصورة: لا تُقسَّم البنود بين عدة أشخاص.", "دورك: الإرشاد وتوضيح الغامض بلغة بسيطة — دون إملاء إجابة أو إيحاء بها."], "take": "الخلاصة: جودة النتيجة تُولد من اختيار المجيب الصحيح قبل أول بند.", "check": [], "task": "", "text": {"head": "1) من يجيب عن البنود؟", "body": "<p>يجيب من يعرف المتعلم في حياته اليومية معرفة مباشرة ومستمرة — الوليّ عادة، أو من يقوم مقامه في الرعاية اليومية. والسبب بنيوي: بنود الاستبيان تصف سلوكًا يظهر في البيت والمدرسة والمواقف العادية، لا سلوكًا يُستحضر في جلسة.</p><ul><li>لا يجيب شخص التقى المتعلم مرات معدودة، مهما كانت خبرته المهنية.</li><li>لا تُقسَّم البنود بين عدة أشخاص يجيب كل منهم عن جزء؛ وحدة المصدر شرط لوحدة الصورة.</li><li>دورك أنت: أن تكون حاضرًا للإرشاد عند الحاجة (توضيح بند غامض بلغة بسيطة) دون أن تُملي إجابة أو توحي بها.</li></ul>"}}, {"kind": "slide", "title": "قاعدة «السلوك المعتاد»", "img": null, "points": ["الجملة التي تُقال قبل البدء: «أجيبوا عما يفعله عادة في الأسابيع الأخيرة — لا عن أفضل يوم ولا عن أسوأ يوم».", "يوم النوم الممتاز والعطلة الهادئة لا يمثلان البروفيل.", "ويوم المرض والسفر وتغيّر الروتين لا يمثله أيضًا.", "عند التردد بين إجابتين: المرجع هو الأغلب تكرارًا، لا الأحدث ولا الأشدّ أثرًا في الذاكرة."], "take": "الخلاصة: اطلب من الأسرة ترديد القاعدة بصياغتها قبل أن تبدأ — ثلاثون ثانية توفّر إعادة تقييم كاملة.", "check": [], "task": "", "text": {"head": "2) قاعدة «السلوك المعتاد»", "body": "<p>القاعدة الذهبية التي تُقال للأسرة قبل أول بند: «أجيبوا عما يفعله عادة في الأسابيع الأخيرة، لا عن أفضل يوم ولا عن أسوأ يوم».</p><ul><li>يوم استثنائي جيد (نوم ممتاز، يوم عطلة هادئ) لا يمثّل البروفيل.</li><li>يوم استثنائي صعب (مرض، سفر، تغيير مفاجئ في الروتين) لا يمثّله أيضًا.</li><li>إن تردد المجيب بين إجابتين، فالمرجع هو الأغلب تكرارًا في الأسابيع الأخيرة، لا الأحدث ولا الأشدّ أثرًا في الذاكرة.</li></ul><p>اشرح هذه القاعدة شفهيًا، ثم اطلب من الأسرة ترديدها بصياغتها قبل أن تبدأ — ثلاثون ثانية هنا توفّر إعادة تقييم كاملة لاحقًا.</p>"}}, {"kind": "slide", "title": "إدارة جلسة الإكمال", "img": null, "points": ["جلسة واحدة متصلة قدر الإمكان، في وقت هادئ بلا مقاطعات — 86 بندًا في فئة 3-14.", "لا مراجعة عكسية: لا تُعدَّل الإجابات السابقة على ضوء اللاحقة؛ الاستبيان يقيس الانطباع الصادق لا لوحة مصطنعة.", "التعب يُدار بوعي: وقوف قصير مقبول؛ ترك معلّق لأيام غير مقبول.", "وقبل الإرسال: تنبيه صريح أن الإرسال نهائي ويستهلك الكود."], "take": "الخلاصة: أغلب أخطاء النصف الثاني من البنود سببها جلسة سيئة الإدارة، لا أسرة مهملة.", "check": [], "task": "", "text": {"head": "3) إدارة جلسة الإكمال", "body": "<ul><li>جلسة واحدة متصلة قدر الإمكان، في وقت هادئ، وبلا مقاطعات — فالبنود كثيرة (86 بندًا في فئة 3-14) والتشتت يولّد إجابات متعجّلة في النصف الثاني.</li><li>لا تُراجَع الإجابات السابقة لتعديلها على ضوء لاحقة؛ الاستبيان يقيس الانطباع الصادق، لا لوحة متّسقة مصطنعة.</li><li>إن تعب المجيب فعلًا، الوقوف القصير مقبول، لكن لا تُترك الجلسة لأيام ثم تُستأنف بذاكرة مختلفة.</li><li>قبل الإرسال النهائي: تنبيه صريح أن الإرسال يستهلك كود التقييم، وأن المراجعة بعد الإرسال غير ممكنة.</li></ul>"}}, {"kind": "slide", "title": "الأخطاء الخمسة التي تُفسد النتيجة", "img": null, "points": ["1 تجميلية: تقديم المتعلم كما نتمنى لا كما هو.", "2 دفاعية: إنكار سلوك قائم خوفًا من النتيجة — والتقرير وثيقة عمل سرية لا حكم على الأسرة.", "3 خلط السياقات: إجابة سلوك المدرسة في بنود البيت أو العكس.", "4 تسرّب التعب: إجابات موحّدة متعجّلة في آخر البنود.", "5 تعدد المجيبين: أسلوبا تقدير مختلفان داخل استبيان واحد."], "take": "تنبيه: كلها تُمنع في خمس دقائق تهيئة؛ ولا يُصلح أيٌّ منها بعد الإرسال إلا بتقييم جديد.", "check": [], "task": "", "text": {"head": "4) الأخطاء الخمسة التي تُفسد النتيجة", "body": "<p>1. الإجابة التجميلية: تقديم المتعلم كما نتمنى أن يكون، لا كما هو — تنتج خطة لأنشطة لا يحتاجها.</p><p>2. الإجابة الدفاعية: إنكار سلوكيات قائمة خوفًا من «وصمة» النتيجة — والتقرير وثيقة عمل سرية، لا حكم على الأسرة.</p><p>3. الخلط بين المواقف: الإجابة عن سلوك المدرسة في بنود البيت أو العكس — كل بند يُجاب في سياقه الظاهر.</p><p>4. التسرّب من التعب: إجابات موحّدة متعجّلة في آخر البنود لتُنهي الجلسة — علامتها نمط منتظم مريب، وعلاجها الوقاية بإدارة الجلسة (القسم 3).</p><p>5. إجابة شخصين متناوبين: أسلوبان مختلفان في التقدير داخل استبيان واحد، فتضيع وحدة القياس.</p><p>كل هذه الأخطاء يمكن منعها في خمس دقائق من التهيئة؛ ولا يمكن إصلاح أي منها بعد الإرسال إلا بتقييم جديد.</p>"}}, {"kind": "slide", "title": "خلاصة الدرس — قائمة تحققك", "img": null, "points": [], "take": "", "check": ["المجيب صاحب معرفة يومية ومصدر واحد.", "أشرح «السلوك المعتاد» وأسمع ترديده قبل البدء.", "جلسة واحدة هادئة متصلة بلا تعديل عكسي.", "تنبيه نهائية الإرسال قبل حدوثه.", "أمنع الأخطاء الخمسة في التهيئة، لا أكتشفها في التقرير."], "task": "مهمة عملية قبل الدرس التالي: اكتب نص تهيئتك للأسرة في خمسة أسطر كحد أقصى: من يجيب، وقاعدة السلوك المعتاد، ونهائية الإرسال — واحفظه عندك."}], "closing": [{"head": "خلاصة الدرس — قائمة تحققك كمختص شريك", "body": "<p>1. أتأكد أن المجيب هو صاحب المعرفة اليومية المباشرة، وأنه مصدر واحد.</p><p>2. أشرح قاعدة «السلوك المعتاد» وأسمع الأسرة تردّدها قبل البدء.</p><p>3. أهيّئ جلسة واحدة هادئة متصلة، وأدير تعب المجيب بوعي.</p><p>4. أنبّه قبل الإرسال إلى أنه نهائي ويستهلك الكود.</p><p>5. أرصد الأخطاء الخمسة وأمنعها في التهيئة، لا أكتشفها في التقرير.</p>"}, {"head": "قبل أن تنتقل", "body": "<p>مهمة عملية: اكتب نص التهيئة الذي ستقوله لأي أسرة قبل الاستبيان — خمسة أسطر كحد أقصى تتضمن: من يجيب، وقاعدة السلوك المعتاد، ونهائية الإرسال. احفظه عندك وردّده حتى يصير تلقائيًا. في الدرس التالي: رحلة النتيجة من الإرسال إلى التقرير.</p>"}], "scenario": {"q": "يقترح أب أن يجيب هو عن نصف البنود وتجيب الأم عن النصف الآخر لتوفير الوقت. ما موقفك؟", "opts": ["اقتراح عملي ممتاز", "يقسم العمل بحسب المجالات التسعة", "لا: مصدر واحد لوحدة الصورة، وهو من يعرف المتعلم يوميا"], "c": 2, "ex": "تعدد المجيبين أحد الأخطاء الخمسة المفسدة للنتيجة: أسلوبا تقدير مختلفان داخل استبيان واحد."}, "quiz": [{"q": "عند تردد الأسرة بين إجابتين عن بند، المرجع هو:", "opts": ["أحدث موقف تتذكره", "الأشد أثرا في الذاكرة", "الأغلب تكرارا في الأسابيع الأخيرة"], "c": 2, "ex": "قاعدة السلوك المعتاد: الأغلب تكرارا، لا الأحدث ولا الأشد."}, {"q": "أي مما يلي من الأخطاء المفسدة للنتيجة؟", "opts": ["إجابات تجميلية تقدم المتعلم كما نتمنى لا كما هو", "الإجابة في وقت هادئ بلا مقاطعات", "سؤال المختص عن بند غامض"], "c": 0, "ex": "التجميلية والدفاعية وخلط السياقات وتسرب التعب وتعدد المجيبين: كلها تمنع في خمس دقائق تهيئة، ولا يصلح أي منها بعد الإرسال."}, {"q": "قبل ضغط زر الإرسال، التنبيه الصريح الواجب هو:", "opts": ["يمكن تعديل الإجابات غدا", "الإرسال نهائي ويستهلك الكود", "النتيجة تصل فورا بلا مراجعة"], "c": 1, "ex": "لا مراجعة عكسية ولا تعديل بعد الإرسال، والتقرير يبنى ويراجع قبل التسليم."}]}, {"n": 6, "title": "رحلة النتيجة: من الإرسال إلى التقرير", "intro": "<p>في نهاية هذا الدرس تستطيع أن تصف للأسرة بدقة ما يحدث بعد ضغط زر «إرسال»: كيف تتحول الإجابات إلى نتيجة، وما الذي يحتويه التقرير، ولماذا يمرّ بمراجعة قبل التسليم، وكيف تُسلّمه للأسرة بمهنية. قراءة التقرير وتفسيره سطرًا سطرًا موضوع المستوى الثاني؛ أما هذا الدرس فعن رحلته وبنيته ودورك عند وصوله.</p>", "slides": [{"kind": "cover", "title": "المستوى الأول: فهم عمل الأداة بكل تفاصيلها", "sub": "الدرس 6: رحلة النتيجة — من الإرسال إلى التقرير", "goals": ["تصف ما يحدث لحظة الإرسال وبعده بدقة", "تعرف بنية التقرير قسمًا قسمًا", "تطبّق مراجعة السلامة قبل التسليم", "تسلّم التقرير في جلسة شرح مهنية"]}, {"kind": "slide", "title": "ما يحدث لحظة الإرسال", "img": null, "points": ["تُغلق الجلسة ويُستهلك كود التقييم — فلا تعديل لاحق على الإجابات.", "تُنظَّم الإجابات على المجالات التسعة، ويُحسب لكل مجال نمطه الغالب من مجموع بنوده.", "تُركَّب التوصيات المناسبة لكل مجال وفق نمطه الغالب.", "يُبنى ملف التقرير باسم المتعلم — وثيقة شخصية للحالة، لا نموذج عام."], "take": "الخلاصة: من لحظة الإرسال تنتقل المسؤولية من الأسرة المجيبة إلى الوثيقة وسلامتها.", "check": [], "task": "", "text": {"head": "1) ما يحدث لحظة الإرسال", "body": "<ul><li>تُغلق الجلسة ويُستهلك كود التقييم؛ فلا تعديل لاحق على الإجابات.</li><li>تُنظَّم الإجابات على المجالات التسعة، ويُحسب لكل مجال النمط الغالب داخله من مجموع بنوده.</li><li>تُركَّب التوصيات المناسبة لكل مجال وفق النمط الغالب فيه.</li><li>يُبنى ملف تقرير باسم المتعلم — فالتقرير وثيقة شخصية للحالة، لا نموذج عام.</li></ul>"}}, {"kind": "slide", "title": "بنية التقرير", "img": "07-home-mid1.png", "points": ["في الأعلى: بيانات الحالة وفئتها وتاريخ التقييم — مرجع التوثيق والمقارنة لاحقًا.", "نتيجة كل مجال: نمطه الغالب ووصف ما يعنيه في السلوك اليومي بلغة يفهمها الوليّ.", "التوصيات العملية المرتبطة بكل مجال — الجسر نحو خطة الأنشطة.", "وملاحظة المختص عند وجودها — بصمتك على الوثيقة."], "take": "تنبيه: لا يُقرأ سطر من التقرير منعزلًا؛ فالسلوك الواحد قد يتداخل فيه أكثر من مجال — تفصيله في المستوى الثاني.", "check": [], "task": "", "text": {"head": "2) بنية التقرير", "body": "<p>يقرأ التقرير من الأعلى إلى الأسفل هكذا:</p><ul><li>بيانات الحالة وفئتها العمرية وتاريخ التقييم — مرجع التوثيق والمقارنة لاحقًا.</li><li>نتيجة كل مجال من المجالات التسعة: نمطه الغالب ووصف ما يعنيه ذلك في السلوك اليومي بلغة يفهمها الوليّ.</li><li>توصيات عملية مرتبطة بكل مجال، تصلح جسرًا نحو خطة الأنشطة.</li><li>ملاحظة المختص عند وجودها — بصمتك المهنية على الوثيقة (القسم 4).</li></ul><p>لاحظ أن التقرير يصف ما يغلب على كل مجال؛ فلا يُقرأ سطر واحد منه منعزلًا عن بقية المجالات — والسلوك الواحد قد يتداخل فيه أكثر من مجال، كما ستفصّل في المستوى الثاني.</p>"}}, {"kind": "slide", "title": "لغة التقرير والمراجعة قبل التسليم", "img": null, "points": ["ثلاث لغات ممكنة: العربية أو الإنجليزية أو الفرنسية، حسب اختيار الأسرة عند التقييم.", "مراجعة سلامة إلزامية: الاسم، الفئة، اللغة، اكتمال الأقسام — قبل أي تسليم.", "خطأ اللغة يُصحَّح قبل التسليم لا بعده (وانظر الدرس 10 عند الحاجة).", "لا تسليم لوثيقة غير مُراجعة ولو بدت صحيحة من أول نظرة."], "take": "الخلاصة: ما يُراجع هنا سلامة الوثيقة؛ أما تفسير محتواها فمبناه المستوى الثاني.", "check": [], "task": "", "text": {"head": "3) لغة التقرير والمراجعة قبل التسليم", "body": "<ul><li>يصدر التقرير بإحدى ثلاث لغات: العربية أو الإنجليزية أو الفرنسية، حسب اختيار الأسرة عند التقييم. خطأ اللغة يُصحَّح قبل التسليم لا بعده (وانظر الدرس 10).</li><li>يمرّ التقرير بمراجعة قبل أن يصل إلى الأسرة: مراجعة سلامة (الاسم، الفئة، اللغة، اكتمال الأقسام). لا تُسلّم تقريرًا لم يمرّ بهذه المراجعة ولو بدت لك بياناته صحيحة من أول نظرة.</li><li>ما يُراجَع هنا سلامة الوثيقة؛ أما تفسير محتواها للأسرة فيُبنى على مستواك الثاني، لا على انطباع القراءة الأولى.</li></ul>"}}, {"kind": "slide", "title": "ملاحظة المختص والتسليم في جلسة شرح", "img": null, "points": ["الملاحظة تسجّل سياقًا تعرفه أنت: ظرفًا عائليًا مؤقتًا أو تغييرًا حديثًا — موجزة وواقعية، بلا تشخيصات جديدة وبلا وعود.", "التسليم في جلسة، لا برسالة عابرة: الصورة العامة أولًا، ثم المجالات الأبرز، ثم معنى التوصيات، ثم الخطوة التالية.", "نسخة للأسرة ونسخة لملف الحالة عندك — فهو وثيقة المقارنة عند إعادة التقييم."], "take": "الخلاصة: تقرير يُسلَّم بلا شرح نصف تقرير؛ والشرح المنضبط نصف المتابعة.", "check": [], "task": "", "text": {"head": "4) ملاحظة المختص وتسليم التقرير", "body": "<ul><li>يمكن أن تُرفق بالتقرير ملاحظة منك كمختص معالج: سياق تعرفه أنت ولا تعرفه الإجابات (ظرف عائلي مؤقت، دواء حديث، تغيير مدرسي) — تُكتب موجزة وواقعية، بلا تشخيصات جديدة وبلا وعود.</li><li>التسليم يكون في جلسة شرح، لا برسالة عابرة: تعرض الصورة العامة أولًا (أين يتركّز البروفيل)، ثم المجالات الأبرز، ثم ما تعنيه التوصيات عمليًا، ثم الخطوة التالية: الخطة.</li><li>تُسلَّم نسخة التقرير للأسرة وتحفظ نسخته في ملف الحالة عندك؛ فهو وثيقة المقارنة عند إعادة التقييم.</li></ul>"}}, {"kind": "slide", "title": "خلاصة الدرس — قائمة تحققك", "img": null, "points": [], "take": "", "check": ["أعرف أن الإرسال يستهلك الكود ويغلق التعديل.", "أصف بنية التقرير قبل وصول أول تقرير فعلي.", "أتحقق: الاسم، الفئة، اللغة، اكتمال الأقسام.", "ملاحظتي موجزة وواقعية بلا تجاوز.", "أسلّم في جلسة شرح تنتهي بخطوة تالية واضحة."], "task": "مهمة عملية قبل الدرس التالي: اكتب قائمة الفحص من 5 بنود التي ستطبّقها على أول تقرير يصلك قبل جلسة تسليمه للأسرة."}], "closing": [{"head": "خلاصة الدرس — قائمة تحققك كمختص شريك", "body": "<p>1. أعرف أن الإرسال يستهلك الكود ويغلق باب التعديل.</p><p>2. أستطيع وصف بنية التقرير قسمًا قسمًا قبل أن يصلني أول تقرير فعلي.</p><p>3. أتحقق من الاسم والفئة واللغة واكتمال الأقسام قبل التسليم.</p><p>4. أكتب ملاحظة مختص موجزة وواقعية عند الحاجة، بلا تجاوز.</p><p>5. أسلّم التقرير في جلسة شرح تنتهي بخطوة تالية واضحة، لا برسالة.</p>"}, {"head": "قبل أن تنتقل", "body": "<p>مهمة عملية: تخيّل وصول أول تقرير إليك، واكتب قائمة الفحص التي ستطبقها عليه قبل جلسة التسليم (من 5 بنود). في الدرس التالي: الخطة والاشتراكات — ما الذي يشتريه كل خيار فعليًا.</p>"}], "scenario": {"q": "أسرة أرسلت الاستبيان قبل دقائق وتطلب استلام التقرير الآن على هاتفها. ما ردك المهني؟", "opts": ["أرسله فور جاهزيته دون جلسة", "أطبع لها مسودة غير مراجعة ريثما يجهز الأصل", "التقرير يبنى مجالا مجالا ويراجع قبل التسليم، ويسلم في جلسة شرح لا برسالة عابرة"], "c": 2, "ex": "تقرير يسلم بلا شرح نصف تقرير، ولا تسليم لوثيقة غير مراجعة ولو بدت صحيحة."}, "quiz": [{"q": "لحظة إرسال الاستبيان يحدث:", "opts": ["تبقى الإجابات قابلة للتعديل 24 ساعة", "يستهلك كود التقييم، وتحسب النتيجة مجالا مجالا، ويبنى التقرير باسم المتعلم", "يفتح كود الخطة تلقائيا لكل حالة"], "c": 1, "ex": "من لحظة الإرسال تنتقل المسؤولية من الأسرة المجيبة إلى الوثيقة وسلامتها."}, {"q": "ملاحظة المختص على التقرير يجب أن تكون:", "opts": ["تشخيصا جديدا يضيفه المختص", "وعدا للأسرة بنتائج الخطة", "سياقا موجزا واقعيا يعرفه المختص عن الحالة، بلا تشخيصات جديدة وبلا وعود"], "c": 2, "ex": "الملاحظة بصمتك على الوثيقة: ظرف مؤقت أو تغيير حديث، باختصار وواقعية."}, {"q": "اكتشفت عند التسليم أن لغة التقرير غير التي طلبتها الأسرة. التصرف:", "opts": ["تترجمه بنفسك وتسلمه", "تسلمه كما هو فالمحتوى واحد", "لا يسلم، ويبلغ بلقطة من رأس التقرير ووصف فيه اللغة الصحيحة المطلوبة"], "c": 2, "ex": "اللغة قرار لحظة التقييم، والتقرير وثيقة رسمية تصدر بلغتها من مصدرها."}]}, {"n": 7, "title": "الخطة والاشتراكات: ماذا يشتري كل خيار؟", "intro": "<p>في نهاية هذا الدرس تستطيع أن تشرح خيارات الاشتراك في الأداة كما هي معروضة للأفراد، وأن تقول بدقة ما يحصل عليه صاحب كل خيار وما لا يحصل عليه، وأن تساعد الأسرة على اختيار ما يناسب حالتها دون ضغط ودون وعود زائدة. هذا الدرس عن اشتراكات الأفراد داخل الأداة فقط.</p>", "slides": [{"kind": "cover", "title": "المستوى الأول: فهم عمل الأداة بكل تفاصيلها", "sub": "الدرس 7: الخطة والاشتراكات — ماذا يشتري كل خيار فعليًا", "goals": ["تشرح خيارات اشتراك الأفراد كما هي معروضة", "تقول ما يشتريه كل خيار وما لا يشتريه بدقة", "تساعد الأسرة على الاختيار من حاجتها", "تتجنّب ضغط البيع ووعود النتائج"]}, {"kind": "slide", "title": "الخيار الأول: البروفيل وحده — 10$", "img": null, "points": ["يشتري: تقييمًا كاملًا واحدًا — الاستبيان بحسب الفئة، والنتيجة مجالًا مجالًا، والتقرير باسم المتعلم بإحدى اللغات الثلاث مع توصياته.", "لا يشمل: خطة الأنشطة الشهرية — ينتهي عند التقرير والتوصيات.", "يناسب: أسرة تريد الصورة الحسية أولًا، أو مختصًا يريد وثيقة التقييم أساسًا لبرنامجه."], "take": "الخلاصة: البروفيل وحده محطة وصف وقياس — لا محطة تدخّل.", "check": [], "task": "", "text": {"head": "1) الخيار الأول: البروفيل وحده — 10$", "body": "<ul><li>ماذا يشتري؟ تقييمًا واحدًا كاملًا: الاستبيان بحسب الفئة العمرية، والنتيجة مجالًا مجالًا، والتقرير باسم المتعلم بإحدى اللغات الثلاث مع توصياته.</li><li>ماذا لا يشمل؟ خطة الأنشطة الشهرية — فالبروفيل وحده ينتهي عند التقرير والتوصيات.</li><li>لمن يناسب؟ أسرة تريد الصورة الحسية لحالتها أولًا، أو مختص يريد وثيقة التقييم أساسًا لبرنامجه الخاص.</li></ul>"}}, {"kind": "slide", "title": "الخيار الثاني: الشهري — 10$ شهريًا، وأول دخول 20$", "img": "06-monthly-plan.png", "points": ["يشتري: خطة أنشطة شهرية مبنية على بروفيل الحالة، أنشطة مصوّرة مرتبة عبر الشهر، تُفتح بكود الخطة.", "أول دخول 20$ لأنه يجمع خطوتين: البروفيل (10$) + الشهر الأول (10$)؛ وبعدها 10$ لكل شهر.", "لا يشمل: متابعة يومية أو مرافقة علاجية — الخطة محتوى منظم تطبّقه الأسرة وتراجعه أنت في مواعيدك."], "take": "الخلاصة: الشهري باب الدخول إلى التدخل بالتزام قصير شهرًا بشهر.", "check": [], "task": "", "text": {"head": "2) الخيار الثاني: الاشتراك الشهري — 10$ شهريًا، وأول دخول 20$", "body": "<ul><li>ماذا يشتري؟ خطة أنشطة شهرية مبنية على بروفيل الحالة: أنشطة مصوّرة مرتبة عبر الشهر، تُفتح بكود الخطة من صفحة الخطة الشهرية.</li><li>أول دخول 20$ لأنه يجمع خطوتين: البروفيل (10$) + الشهر الأول من الخطة (10$). وبعدها يستمر الاشتراك بـ10$ لكل شهر.</li><li>ماذا لا يشمل؟ متابعة يومية فردية أو مرافقة علاجية — الخطة محتوى منظم تطبّقه الأسرة وتراجعه أنت في مواعيدك المعتادة، لا خدمة مرافقة.</li><li>لمن يناسب؟ أسرة تريد البدء بخطة بأنشطة جاهزة مع إبقاء الالتزام قصيرًا شهرًا بشهر.</li></ul>"}}, {"kind": "slide", "title": "الخيار الثالث: السنوي — 100$", "img": null, "points": ["يشتري: البروفيل + سنة كاملة من خطة الأنشطة (12 شهرًا).", "بسعر أقل من مجموع الاشتراك الشهري عبر السنة نفسها.", "لماذا يوجد؟ لأن أثر الخطة تراكمي: أشهر متتالية من التطبيق وإعادة القياس، لا شهر متقطع.", "يناسب: أسرة اقتنعت وتريد رحلة كاملة بلا تجديدات متكررة."], "take": "الخلاصة: السنوي خيار الاستمرارية — وهو منطق بناء البروفيل نفسه.", "check": [], "task": "", "text": {"head": "3) الخيار الثالث: الاشتراك السنوي — 100$", "body": "<ul><li>ماذا يشتري؟ البروفيل + سنة كاملة من خطة الأنشطة (12 شهرًا) بسعر أقل من مجموع الاشتراك الشهري عبر السنة نفسها.</li><li>لماذا يوجد؟ لأن أثر خطة الأنشطة تراكمي: أشهر متتالية من التطبيق وإعادة القياس، لا شهر واحد متقطع. السنوي هو خيار الاستمرارية.</li><li>لمن يناسب؟ أسرة اقتنعت بعد البروفيل أو الشهر الأول وتريد رحلة كاملة بلا تجديدات متكررة.</li></ul>"}}, {"kind": "slide", "title": "كيف تساعد الأسرة على الاختيار؟", "img": null, "points": ["ابدأ من حاجة الحالة: لا بروفيل بعد؟ ابدأ بالبروفيل. تقرير موجود وتريد التدخل؟ ادخل الخطة.", "اعرض الفرق ببساطة: تقرير فقط / تقرير + أنشطة شهرية / تقرير + أنشطة سنة كاملة.", "بلا ضغط ندرة وبلا وعود نتائج — الاختيار المستعجل يرتد فتورًا في التطبيق.", "ووثّق الاختيار وتاريخ البدء في ملف الحالة؛ فالتجديد وإعادة التقييم يُبنيان عليه."], "take": "الخلاصة: دورك أن يختاروا بفهم، لا أن يختاروا بسرعة.", "check": [], "task": "", "text": {"head": "4) كيف تساعد الأسرة على الاختيار؟", "body": "<ul><li>ابدأ من حاجة الحالة لا من الخيار الأعلى: من لا يعرف البروفيل بعد، يبدأ بالبروفيل؛ ومن عنده تقرير ويريد التدخل، يدخل الخطة.</li><li>اعرض الفرق بجدول كلامي بسيط: (التقرير فقط) مقابل (تقرير + أنشطة شهرية) مقابل (تقرير + أنشطة سنة كاملة).</li><li>لا تستخدم ضغط الندرة ولا وعود النتائج؛ الاختيار المستعجَل يرتدّ إلغاءً أو فتورًا في التطبيق.</li><li>وثّق اختيار الأسرة وتاريخ بدء الاشتراك في ملف الحالة؛ فمواعيد إعادة التقييم والتجديد تُبنى عليه.</li></ul>"}}, {"kind": "slide", "title": "خلاصة الدرس — قائمة تحققك", "img": null, "points": [], "take": "", "check": ["أعرف الأسعار: 10$ / شهري 10$ (أول دخول 20$) / سنوي 100$.", "أفرّق بين «تقرير» و«خطة أنشطة» في كل شرح.", "أوضّح أن الخطة محتوى منظم لا مرافقة يومية.", "أختار مع الأسرة من حاجة الحالة، بلا ضغط ولا وعود.", "أوثّق اختيار الأسرة وتاريخ بدء اشتراكها."], "task": "مهمة عملية قبل الدرس التالي: اكتب شرحًا من سطر واحد لكل خيار كما ستقوله لأسرة تسأل «ما الفرق بين الخيارات؟» — بالأرقام نفسها في هذا الدرس."}], "closing": [{"head": "خلاصة الدرس — قائمة تحققك كمختص شريك", "body": "<p>1. أعرف سعر كل خيار وما يشتريه فعليًا: بروفيل 10$، شهري 10$ (أول دخول 20$)، سنوي 100$.</p><p>2. أفرّق بوضوح بين «تقرير» و«خطة أنشطة» عند أي شرح لأسرة.</p><p>3. أوضّح أن الخطة محتوى منظّم، لا مرافقة يومية.</p><p>4. أساعد على الاختيار من حاجة الحالة، بلا ضغط وبلا وعود نتائج.</p><p>5. أوثّق اختيار الأسرة وتاريخ بدء اشتراكها في ملف الحالة.</p>"}, {"head": "قبل أن تنتقل", "body": "<p>مهمة عملية: اكتب شرحًا من 3 أسطر لكل خيار كما ستقوله لأسرة تسأل «ما الفرق بين الخيارات؟» — سطر واحد لكل خيار، بالأرقام نفسها الواردة في هذا الدرس. في الدرس التالي: «مجال اليوم» وحدود المجاني.</p>"}], "scenario": {"q": "أسرة تحمل تقرير بروفيل من جهة أخرى وتريد البدء بأنشطة الخطة عندكم فورا. ما التوجيه الصحيح داخل منظومة أوسع؟", "opts": ["خطة أوسع تبنى على بروفيل الحالة داخل الأداة، فيبدأ المسار بالبروفيل ثم الخطة", "أي تقرير بروفيل يكفي للبدء", "نبدأ بمجال اليوم شهرا كاملا ثم نقرر"], "c": 0, "ex": "ابدأ من حاجة الحالة: لا بروفيل داخل الأداة بعد؟ ابدأ بالبروفيل، فالخطة مبنية على نتيجته مجالا مجالا."}, "quiz": [{"q": "أول دخول في الاشتراك الشهري 20 دولارا لأنه:", "opts": ["رسوم إدارية لفتح الحساب", "سعر تجريبي للشهر الأول", "يجمع خطوتين: البروفيل 10 دولارات والشهر الأول 10 دولارات"], "c": 2, "ex": "بعد أول دخول يصير الاشتراك 10 دولارات لكل شهر."}, {"q": "ما الذي لا يشمله اشتراك الخطة بأي صيغة؟", "opts": ["متابعة يومية ومرافقة علاجية", "أنشطة مصورة مرتبة عبر الشهر", "خطة مبنية على بروفيل الحالة"], "c": 0, "ex": "الخطة محتوى منظم تطبقه الأسرة وتراجعه أنت في مواعيدك، لا مرافقة يومية."}, {"q": "عند مساعدة أسرة على اختيار الخيار المناسب، تبدأ من:", "opts": ["العرض الأغلى دائما", "حاجة الحالة ومرحلتها: بروفيل أولا أم خطة", "ضغط الندرة وسرعة القرار"], "c": 1, "ex": "دورك أن يختاروا بفهم لا بسرعة، وبلا وعود نتائج."}]}, {"n": 8, "title": "مجال اليوم والتجربة: حدود المجاني", "intro": "<p>في نهاية هذا الدرس تستطيع أن تستعمل «مجال اليوم» أداةَ تعريف صحيحة مع الأسر المترددة: تعرف ما الذي يفتح مجانًا كل يوم، وما الذي يبقى للمشتركين فقط، وكيف تقدّم المجاني بلا أن توحي بأن الأداة «جُرّبت» كاملة أو أن المجاني بديل عن التقييم.</p>", "slides": [{"kind": "cover", "title": "المستوى الأول: فهم عمل الأداة بكل تفاصيلها", "sub": "الدرس 8: «مجال اليوم» والتجربة — ما يراه الزائر وما لا يراه", "goals": ["تعرف دورة الأسبوع لمجال اليوم", "تفرّق بين ما يراه الزائر وما يبقى للمشتركين", "تستعمل المجاني أداة تعريف مهنية", "لا تقدّمه بديلًا عن التقييم أبدًا"]}, {"kind": "slide", "title": "ما «مجال اليوم»؟", "img": "a5-today.png", "points": ["نافذة الأداة المجانية للجميع: مجال حسي واحد يفتح بأنشطته كاملة لذلك اليوم فقط (today.html)، يدخله الزائر من شريط «هدية اليوم» أو زر «جرّب مجانًا».", "يغلق منتصف الليل ويأتي مجال اليوم التالي.", "دورة الأسبوع ثابتة: الجمعة اللمس، السبت الدهليزي، الأحد الحس العميق، الاثنين الشم والتذوق، الثلاثاء الأصوات، الأربعاء البصري، الخميس الحس الداخلي."], "take": "الخلاصة: سبعة مجالات تدور على الأسبوع — ومجالان لا يدخلان الدورة أبدًا (الشريحة 4).", "check": [], "task": "", "text": {"head": "1) ما «مجال اليوم»؟", "body": "<p>صفحة «مجال اليوم» (sensory.awsaa.ca/today.html) هي نافذة الأداة المجانية المفتوحة للجميع: مجال حسي واحد يفتح بأنشطته كاملة في ذلك اليوم فقط، ثم يغلق عند منتصف الليل ليأتي مجال اليوم التالي. يدخلها الزائر من شريط «هدية اليوم» في واجهة الأداة أو من زر «جرّب مجانًا — مجال اليوم».</p><p>دورة الأسبوع ثابتة: الجمعة اللمس، السبت الدهليزي، الأحد الحس العميق، الاثنين الشم والتذوق، الثلاثاء الأصوات، الأربعاء البصري، الخميس الحس الداخلي (الوعي الداخلي).</p>"}}, {"kind": "slide", "title": "ما يراه الزائر", "img": "12-preview.png", "points": ["أنشطة حقيقية من بنك الأداة في مجال اليوم، كما هي داخل الخطة: الاسم والصورة وطريقة التنفيذ والتدرّج.", "وقسم «عاين قبل أن تشترك»: 5 أنشطة حقيقية من الشهر الأول بلا كود وبلا دفع.", "صورة صادقة عن الأسلوب والمنهجية — فالمجاني عيّنة من المنتج نفسه لا نسخة تجميلية."], "take": "الخلاصة: قوة المجاني أنه حقيقي؛ وحدوده أنه عام غير مبني على بروفيل أي حالة.", "check": [], "task": "", "text": {"head": "2) ما يراه الزائر", "body": "<ul><li>أنشطة حقيقية من بنك الأداة في مجال اليوم، كما هي داخل الخطة: اسم النشاط وصورته وطريقة تنفيذه ومستويات تدرّجه.</li><li>قسم «عاين قبل أن تشترك» يعرض أيضًا 5 أنشطة حقيقية من الشهر الأول بلا كود وبلا دفع — معاينة صريحة للمستوى والمنهجية.</li><li>صورة صادقة عن أسلوب الأداة: كيف تُكتب الأنشطة، وكيف تُقدَّم للأسرة.</li></ul><p>المجاني إذن ليس نسخة تجميلية؛ إنه عيّنة من المنتج نفسه — وهذه قوته وضعفه الإداري معًا (القسم 4).</p>"}}, {"kind": "slide", "title": "ما لا يراه الزائر", "img": "06-monthly-plan.png", "points": ["الانتباه والاجتماعي-العاطفي للمشتركين فقط — لا يفتحان في مجال اليوم أبدًا.", "لا تقييم ولا تقرير: الزائر يرى أنشطة مجال عامة، لا أنشطة مبنية على بروفيل حالة بعينها.", "لا خطة مرتبة عبر أشهر ولا متابعة ولا إعادة قياس — وصفحة الخطة الشهرية مقفلة بشاشة قفل إلا بكود."], "take": "الجملة الدقيقة للأسرة: «مجال اليوم يريكم كيف تبدو الأنشطة؛ والتقييم هو ما يجعلها أنشطة ابنكم أنتم».", "check": [], "task": "", "text": {"head": "3) ما لا يراه الزائر", "body": "<ul><li>الانتباه والاجتماعي-العاطفي لا يفتحان في «مجال اليوم» أبدًا — يبقيان للمشتركين فقط، من مجالات الأداة التسعة تعمل في الدورة سبعة.</li><li>لا تقييم ولا تقرير: الزائر يرى أنشطة مجال واحد عامة، لا أنشطة مبنية على بروفيل حالة بعينها.</li><li>لا خطة مرتبة عبر أشهر، ولا متابعة، ولا إعادة قياس.</li><li>صفحة الخطة الشهرية نفسها مقفلة للزائر بشاشة قفل: محتوى الشهر الكامل لا يُفتح إلا بكود خطة.</li></ul><p>الصياغة الدقيقة التي تقولها للأسرة: «مجال اليوم يريكم كيف تبدو الأنشطة؛ والتقييم هو ما يجعلها أنشطة ابنكم أنتم».</p>"}}, {"kind": "slide", "title": "كيف تستعمله مهنيًا؟", "img": null, "points": ["وجّه المترددين إليه أولًا قبل أي حديث اشتراك: تجربة حقيقية تختصر نقاشًا طويلًا.", "اختر يوم المجال الذي يهم الأسرة من دورة الأسبوع، لا إحالة عشوائية.", "لا تقدّمه «تجربة كاملة للأداة» ولا كافيًا لتكوين رأي عن حالة بعينها.", "ونظّم إحالاتك على إيقاعه: ما فات من أيام الأسبوع يُستدرك في دورته القادمة فقط."], "take": "الخلاصة: المجاني باب تعريف ممتاز — بشرط أن تبقى حدوده واضحة في كلامك كما هي في النظام.", "check": [], "task": "", "text": {"head": "4) كيف تستعمله مهنيًا؟", "body": "<ul><li>وجّه الأسرة المترددة إلى مجال اليوم قبل أي حديث عن اشتراك: تجربة حقيقية تختصر نقاشًا طويلًا.</li><li>نبّهها إلى يوم المجال الذي يهمّها من دورة الأسبوع، بدل أن تدخل عشوائيًا فتصادف مجالًا لا يعنيها.</li><li>لا تقدّم المجاني على أنه «تجربة الأداة كاملة» ولا على أنه يكفي لتكوين رأي عن حالة بعينها — الأنشطة العامة ليست خطة حالة.</li><li>لاحظ حدود النافذة عند التخطيط: ما فات من أيام الأسبوع لا يُستدرك إلا في دورته القادمة؛ نظّم إحالاتك على هذا الإيقاع.</li></ul>"}}, {"kind": "slide", "title": "خلاصة الدرس — قائمة تحققك", "img": null, "points": [], "take": "", "check": ["أعرف دورة الأسبوع وأيام كل مجال.", "أفرّق بين ما يراه الزائر وما لا يراه.", "الانتباه والاجتماعي-العاطفي للمشتركين دائمًا.", "أوجّه المترددين للمجاني بيومه المناسب.", "لا أقدّم المجاني بديلًا عن التقييم."], "task": "مهمة عملية قبل الدرس التالي: افتح صفحة «مجال اليوم»: حدّد مجال اليوم الحالي، ونشاطًا أعجبك، والجملة التي ستشرح بها الفرق بينه وبين الخطة الكاملة."}], "closing": [{"head": "خلاصة الدرس — قائمة تحققك كمختص شريك", "body": "<p>1. أعرف دورة الأسبوع السباعية لمجال اليوم وأيام كل مجال.</p><p>2. أفرّق بين ما يراه الزائر (أنشطة عيّنة) وما لا يراه (تقييم وتقرير وخطة).</p><p>3. أعرف أن الانتباه والاجتماعي-العاطفي للمشتركين فقط دائمًا.</p><p>4. أوجّه الأسر المترددة إلى المجاني أولًا وبيومه المناسب.</p><p>5. لا أقدّم المجاني بديلًا عن التقييم ولا تجربة كاملة للأداة.</p>"}, {"head": "قبل أن تنتقل", "body": "<p>مهمة عملية: افتح صفحة «مجال اليوم» الآن، وحدّد: مجال اليوم الحالي، ونشاطًا واحدًا أعجبك فيه، والجملة التي ستقولها لأسرة لتشرح لها الفرق بين ما رأته وبين الخطة الكاملة. في الدرس التالي: حدود الأداة وحدود دورك كمختص.</p>"}], "scenario": {"q": "أسرة تريد مجال الحس العميق في مجال اليوم، واليوم الثلاثاء وهو يوم الأصوات. ما الصواب؟", "opts": ["أفتحه لها من حساب العيادة", "دورة الأسبوع ثابتة: الحس العميق يوم الأحد، وما فات يستدرك في الدورة القادمة، أو بالاشتراك في أي وقت", "تنتظر شهرا كاملا حتى يتاح"], "c": 1, "ex": "سبعة مجالات تدور على أيام الأسبوع، ونظم إحالاتك على إيقاعها لا عشوائيا."}, "quiz": [{"q": "المجالان اللذان لا يفتحان في مجال اليوم أبدا هما:", "opts": ["اللمس والبصري", "الأصوات والدهليزي", "الانتباه والاجتماعي-العاطفي"], "c": 2, "ex": "يبقيان للمشتركين فقط مهما كان يوم الأسبوع."}, {"q": "قسم عاين قبل أن تشترك يعرض:", "opts": ["واجهة تجميلية من صور عامة", "5 أنشطة حقيقية من الشهر الأول بلا كود وبلا دفع", "نتائج حالات سابقة بأسمائها"], "c": 1, "ex": "المجاني عينة من المنتج نفسه لا نسخة تجميلية، وقوته أنه حقيقي."}, {"q": "الجملة الدقيقة التي تصف بها مجال اليوم لأسرة هي:", "opts": ["هو تجربة كاملة للأداة أسبوعا", "يغنيكم عن التقييم إن تابعتموه بانتظام", "مجال اليوم يريكم كيف تبدو الأنشطة، والتقييم هو ما يجعلها أنشطة ابنكم أنتم"], "c": 2, "ex": "حدود المجاني واضحة في النظام، ويجب أن تبقى واضحة في كلامك أيضا."}]}, {"n": 9, "title": "حدود الأداة وحدود دورك", "intro": "<p>في نهاية هذا الدرس تستطيع أن ترسم حدود الأداة بدقة سريرية وتقنية: ما الذي تقيسه فعلًا وما الذي لا تقيسه، وما الذي تستطيع أنت قوله للأسرة وما يتجاوز دورك، ومتى تتحول الحالة من «حالة أداة» إلى «إحالة سريرية إلى المؤسس». هذا الدرس سريري وتقني فقط: حدود القياس وحدود الممارسة.</p>", "slides": [{"kind": "cover", "title": "المستوى الأول: فهم عمل الأداة بكل تفاصيلها", "sub": "الدرس 9: حدود الأداة وحدود دورك — ما لا تقيسه الأداة، ومتى تُحال الحالة إلى المؤسس", "goals": ["ترسم ما تقيسه الأداة وما لا تقيسه بدقة", "تبقى داخل حدود دورك واختصاصك معها", "تتعرّف حالات الإحالة السريرية إلى المؤسس", "ترفع الإحالة مكتوبًا بالطريقة المعتمدة"]}, {"kind": "slide", "title": "ما تقيسه الأداة فعلًا", "img": "11-pricing.png", "points": ["البروفيل الحسي كما يظهر في السلوك اليومي: إجابات منظمة عن بنود سلوكية يجيب عنها من يعرف الحالة يوميًا.", "تُقرأ مجالًا مجالًا عبر المجالات التسعة فيخرج لكل مجال نمطه الغالب.", "وتُبنى على ذلك التوصيات وخطة الأنشطة — هذا هو نطاقها الكامل.", "بفئتين عمريتين عاملتين: 0-3 و3-14 (وفئة أكبر من 14 مجمّدة — عند طلب العيادات فقط)."], "take": "الخلاصة: قياس وصفي منظّم للسلوك الحسي — قوتها في وضوح نطاقها.", "check": [], "task": "", "text": {"head": "1) ما تقيسه الأداة فعلًا", "body": "<p>تقيس الأداة البروفيل الحسي للمتعلم كما يظهر في سلوكه اليومي: إجابات منظمة عن بنود سلوكية، تُقرأ مجالًا مجالًا (تسعة مجالات) فيخرج لكل مجال نمطه الغالب، وتُبنى على ذلك التوصيات وخطة الأنشطة. هذا هو نطاقها الكامل — قياس وصفي للسلوك الحسي من مصدر يعرف الحالة يوميًا، بأدوات مصممة لفئتين عمريتين عاملتين (0-3 و3-14).</p>"}}, {"kind": "slide", "title": "ما لا تقيسه الأداة", "img": null, "points": ["لا تشخّص: ليست أداة تشخيص للتوحد ولا لأي اضطراب؛ نتيجتها بروفيل حسي لا حكم طبي.", "لا تقيس الذكاء ولا التحصيل ولا اللغة — خارج بنودها كليًا.", "لا تفحص جسديًا: لا سمع ولا بصر ولا وظائف عصبية؛ أي اشتباه عضوي يسبقها ويعلو عليها.", "لا تتنبأ ولا تعد: لا تقول ماذا سيحدث بعد سنة، ولا تضمن أثرًا علاجيًا لنشاط."], "take": "تنبيه: كل ما لا تقيسه إن نُسب إليها صار ادعاءً باسم أوسع — وحدود الادعاء جزء من المصداقية.", "check": [], "task": "", "text": {"head": "2) ما لا تقيسه الأداة", "body": "<ul><li>لا تشخّص: ليست أداة تشخيص للتوحد ولا لأي اضطراب آخر؛ نتيجتها بروفيل حسي، لا حكمًا طبيًا ولا نفسيًا شاملًا.</li><li>لا تقيس الذكاء ولا التحصيل ولا اللغة: قدرات المتعلم المعرفية واللغوية والأكاديمية خارج بنودها كليًا.</li><li>لا تفحص جسديًا: لا تقييم سمعًا ولا بصرًا ولا وظائف عصبية ولا حساسية غذائية مخبرية؛ أي اشتباه في سبب عضوي يسبقها ويعلو عليها.</li><li>لا تقرأ سياقًا لم يُروَ لها: ما لم يظهر في إجابات المجيب لا وجود له في النتيجة — وهنا تلتقي حدود الأداة بجودة الإكمال (الدرس 5).</li><li>لا تتنبأ ولا تعد: لا تقول ماذا سيحدث بعد سنة، ولا تضمن أثرًا علاجيًا لأي نشاط.</li></ul>"}}, {"kind": "slide", "title": "حدود دورك كمختص مع الحالة", "img": null, "points": ["داخل دورك: التهيئة، وإدارة التقييم بجودة، وقراءة التقرير وتفسيره في حدود ما يقيسه، ودمجه في برنامج حالتك، والمتابعة وإعادة القياس.", "خارج دورك: أن تنسب للأداة ما لم تقله، أو تحوّل توصية عامة إلى وعد نتيجة لأسرة بعينها.", "خارج دورك: الحكم على مجال من ملاحظة عينية بلا قياس — الممارسة التي وُجدت الأداة لتصحيحها.", "وخارج دورك: تجاوز اختصاصك المهني الأصلي بحجة نتيجة بروفيل؛ فالبروفيل يخدم اختصاصك لا يوسّعه."], "take": "الخلاصة: كلما ضاق ادعاؤك عما تقيسه الأداة فعلًا، اتسعت ثقة الأسر بك وبها.", "check": [], "task": "", "text": {"head": "3) حدود دورك كمختص مع الحالة", "body": "<p>داخل دورك: تهيئة الأسرة، وإدارة التقييم بجودة، وقراءة التقرير وتفسيره في حدود ما يقيسه، ودمج نتيجته في برنامج حالتك العام، ومتابعة التطبيق وإعادة القياس.</p><p>وخارج دورك مع هذه الأداة تحديدًا:</p><ul><li>أن تنسب للأداة ما لم تقله: لا «الأداة أثبتت أن عند المتعلم كذا» في أي مجال لا تقيسه أصلًا.</li><li>أن تحوّل التوصية العامة إلى وعد نتيجة لأسرة بعينها.</li><li>أن تحكم على حالة من ملاحظة عينية واحدة وتسمّي مجالًا بلا قياس — الممارسة التي وُجدت هذه الأداة أصلًا لتصحيحها.</li><li>أن تتجاوز اختصاصك المهني الأصلي بحجة نتيجة بروفيل: البروفيل يخدم اختصاصك، لا يوسّعه.</li></ul>"}}, {"kind": "slide", "title": "متى تُحال الحالة إلى المؤسس إحالة سريرية؟", "img": null, "points": ["نتيجة تتعارض حادًا مع ملاحظتك السريرية المباشرة ولا يفسرها سياق الإجابات.", "مؤشرات سبب عضوي محتمل (سمع، بصر، ألم، نوبات) — الإحالة الطبية أصلًا، وإعلام المؤسس بالتوازي.", "حالة مركّبة تتداخل فيها مجالات كثيرة ولا تستطيع ترتيب أولوياتها بثقة.", "أسئلة أسرية تتجاوز البروفيل إلى تشخيص أو خطة شاملة تُطلب باسم أوسع."], "take": "طريقة الإحالة: وصف مكتوب موجز للحالة وسبب الإحالة (وما يدعمه عند الحاجة) إلى ماسنجر صفحة المؤسس — إحالة موثّقة لا حديث عابر.", "check": [], "task": "", "text": {"head": "4) متى تُحال الحالة إلى المؤسس إحالة سريرية؟", "body": "<p>تُرفع الحالة إلى المؤسس عندما تتجاوز نطاق الأداة أو نطاق القراءة المعتادة، ومن أمثلتها:</p><ul><li>نتيجة تتعارض تعارضًا حادًا مع ملاحظتك السريرية المباشرة ولا يفسرها سياق الإجابات.</li><li>مؤشرات في كلام الأسرة أو سلوك المتعلم توحي بسبب عضوي محتمل (سمع، بصر، ألم، نوبات) — هنا الإحالة الطبية أصلًا، وإعلام المؤسس بالتوازي.</li><li>حالة مركّبة تتداخل فيها مجالات كثيرة بصورة لا تستطيع ترتيب أولوياتها بثقة.</li><li>أسئلة أسرية تتجاوز البروفيل إلى تشخيص أو خطة علاجية شاملة يطلبونها باسم أوسع.</li></ul><p>تتم الإحالة بطريقة التواصل المعتمدة: وصف مكتوب موجز للحالة وسبب الإحالة (وما يدعمه من لقطات أو مستندات عند الحاجة) إلى ماسنجر صفحة المؤسس — إحالة مكتوبة موثّقة، لا أحاديث عابرة.</p>"}}, {"kind": "slide", "title": "خلاصة الدرس — قائمة تحققك", "img": null, "points": [], "take": "", "check": ["أسرد ما تقيسه الأداة وما لا تقيسه بلا تردد.", "لا ترتبط كلمة «تشخيص» بالأداة في كلامي أبدًا.", "أبقى داخل اختصاصي: البروفيل يخدمني ولا يوسّعني.", "لا حكم على مجال بلا قياس.", "أعرف حالات الإحالة وأرفعها مكتوبًا بالطريقة المعتمدة."], "task": "مهمة عملية قبل الدرس التالي: اكتب ثلاث جمل جاهزة: ما لا تقيسه الأداة لوليّ متحمس، ورفض الحكم بلا قياس، وافتتاح إحالة سريرية إلى المؤسس."}], "closing": [{"head": "خلاصة الدرس — قائمة تحققك كمختص شريك", "body": "<p>1. أستطيع سرد ما تقيسه الأداة وما لا تقيسه بلا تردد.</p><p>2. لا أسمح لكلمة «تشخيص» أن ترتبط بالأداة في أي كلام مع أسرة.</p><p>3. أبقى داخل اختصاصي: البروفيل يخدمني ولا يوسّع صلاحياتي.</p><p>4. لا حكم على مجال من ملاحظة عينية بلا قياس — أبدًا.</p><p>5. أعرف حالات الإحالة السريرية للمؤسس وأرفعها مكتوبًا بالطريقة المعتمدة.</p>"}, {"head": "قبل أن تنتقل", "body": "<p>مهمة عملية: اكتب ثلاث جمل جاهزة عندك: جملة تشرح ما لا تقيسه الأداة لوليّ متحمّس يطلب منها أكثر من نطاقها، وجملة ترفض بها الحكم على مجال بلا قياس، وجملة تفتتح بها إحالة سريرية إلى المؤسس. في الدرس التالي والأخير: الأعطال الشائعة وبروتوكول التصرف والتبليغ.</p>"}], "scenario": {"q": "ولي يطلب أن تكتب في ملف ابنه أن أداة البروفيل أثبتت إصابته بالتوحد ليقدمه لجهة رسمية. ما موقفك؟", "opts": ["أكتبها فالنتيجة قوية", "أكتبها بصيغة مخففة ترضي الطرفين", "أرفض باحترام: نتيجة الأداة بروفيل حسي وصفي، لا حكم تشخيصي، ونسبته إليها ادعاء خارج نطاقها ونطاق دوري"], "c": 2, "ex": "كل ما لا تقيسه الأداة إن نسب إليها صار ادعاء باسم أوسع، وحدود الادعاء جزء من المصداقية."}, "quiz": [{"q": "الأداة لا تقيس أيا مما يلي:", "opts": ["النمط الغالب في كل مجال حسي", "الذكاء والتحصيل واللغة", "البروفيل كما يظهر في السلوك اليومي"], "c": 1, "ex": "نطاقها الكامل: وصف حسي سلوكي منظم عبر تسعة مجالات، لا أكثر."}, {"q": "من الحالات التي تحال سريريا إلى المؤسس:", "opts": ["كل حالة جديدة في العيادة", "أسرة تكثر من الأسئلة", "نتيجة تتعارض حادا مع ملاحظتك السريرية ولا يفسرها سياق الإجابات"], "c": 2, "ex": "ومنها أيضا مؤشرات سبب عضوي محتمل، والحالات المركبة التي لا ترتب أولوياتها بثقة."}, {"q": "الحكم على مجال حسي لحالة من ملاحظة عينية سريعة بلا قياس هو:", "opts": ["خبرة مهنية مشروعة", "الممارسة التي وجدت الأداة لتصحيحها، وهو خارج دورك", "مقبول عند ضيق الوقت"], "c": 1, "ex": "النمط يقاس ولا يخمن، وهذه قاعدة المنظومة كلها."}]}, {"n": 10, "title": "أعطال شائعة وبروتوكول التبليغ", "intro": "<p>في نهاية هذا الدرس تستطيع أن تتعامل مع المشاكل التشغيلية الشائعة بهدوء وترتيب: تعرف ما يُحلّ عندك في دقيقة، وما يحتاج تبليغًا رسميًا، وكيف يُكتب التبليغ الصحيح الذي يُنفَّذ من أول مرة. القاعدة التي تحكم الدرس كله: لا مشكلة تُبلَّغ بلا لقطة شاشة ووصف مكتوب.</p>", "slides": [{"kind": "cover", "title": "المستوى الأول: فهم عمل الأداة بكل تفاصيلها", "sub": "الدرس 10: أعطال ومشاكل شائعة — بروتوكول التصرف والتبليغ المعتمد", "goals": ["تطبّق بروتوكول التبليغ الرسمي بلا استثناء", "تفكّ عطل الكود بترتيب فحص صحيح", "تعالج لغات التقارير والجلسات غير المكتملة", "تختصر على الجميع وقت التخمين المتبادل"]}, {"kind": "slide", "title": "بروتوكول التبليغ الرسمي", "img": null, "points": ["1 لقطة شاشة للمشكلة كما تظهر تمامًا: الصفحة ورسالة الخطأ والخطوة التي توقفت عندها (مع إخفاء بيانات لا لزوم لها).", "2 وصف مكتوب من أربعة عناصر: اسم الحالة أو معرفها، نوع الكود، الخطوة المنفّذة، وما حدث بالضبط ومتى.", "3 الإرسال إلى ماسنجر صفحة المؤسس — اللقطة والوصف في الرسالة نفسها.", "لا تبليغ شفهيًا ولا وصف بلا لقطة — فهو لا يُقبل، وبلا صورة يتحول التبليغ إلى تخمين متبادل."], "take": "الخلاصة: البروتوكول نفسه يحكم طلب كود جديد (الدرس 4) وكل مشكلة دخول أو غيرها.", "check": [], "task": "", "text": {"head": "1) بروتوكول التبليغ الرسمي", "body": "<p>لأي مشكلة لا تحلّها الخطوات المحلية في هذا الدرس، التبليغ المعتمد ثلاث خطوات لا رابع لها:</p><p>1. لقطة شاشة للمشكلة كما تظهر تمامًا: الصفحة، ورسالة الخطأ إن وجدت، والكود أو الخطوة التي توقف عندها (مع إخفاء أي بيانات شخصية لا لزوم لها).</p><p>2. وصف مكتوب من أربعة عناصر: اسم الحالة أو معرفها عندك، نوع الكود المستعمل، ما الخطوة التي كنت تنفّذها، وما الذي حدث بالضبط (ومتى).</p><p>3. الإرسال إلى ماسنجر صفحة المؤسس — لقطة + وصف في الرسالة نفسها.</p><p>لا يُقبل تبليغ شفهي ولا وصف بلا لقطة: بلا صورة للمشكلة يتحول التبليغ إلى تخمين متبادل يستهلك وقت الجميع. وينطبق البروتوكول نفسه على طلب كود جديد (الدرس 4).</p>"}}, {"kind": "slide", "title": "كود لا يعمل — الفحص بالترتيب", "img": "a4-code.png", "points": ["1 الصياغة: أعد قراءة الكود من مصدره المكتوب حرفًا حرفًا — أغلب الأعطال حرف منسوخ خطأ أو مسافة عند اللصق.", "2 النوع والموضع: كود تقييم في باب التقييم وكود خطة في باب الخطة — كثير من «الأعطال» باب خاطئ.", "3 الاستهلاك السابق: راجع سجل أكوادك؛ فالكود المستهلَك لا يعمل وهذا سلوك صحيح لا عطل.", "4 إن سلمت الخطوات: بلّغ بالبروتوكول — لقطة شاشة الرفض + الوصف متضمنًا الكود ونوعه."], "take": "الخلاصة: ثلاث دقائق فحص مرتب توفّر أغلب التبليغات، وتجعل الباقي قابلًا للتنفيذ فورًا.", "check": [], "task": "", "text": {"head": "2) كود لا يعمل", "body": "<p>رتّب الفحص هكذا قبل أي تبليغ:</p><p>1. الصياغة: أعد قراءة الكود من مصدره المكتوب حرفًا حرفًا — أكثر الأعطال من حرف منسوخ خطأ أو مسافة زائدة عند اللصق.</p><p>2. النوع والموضع: هل هذا كود تقييم يُدخل في شاشة التقييم؟ كثير من «الأعطال» كود خطة يُجرَّب في باب التقييم أو العكس.</p><p>3. الاستهلاك السابق: هل استُعمل هذا الكود من قبل؟ راجع سجل أكوادك (الدرس 4) — كود مستهلَك لا يعمل، وهذا سلوك صحيح لا عطل.</p><p>4. إن سلمت الخطوات الثلاث وبقي الرفض: بلّغ بالبروتوكول — لقطة لشاشة الرفض كما هي + وصف يتضمن الكود نفسه ونوعه.</p>"}}, {"kind": "slide", "title": "تقرير بلغة غير المطلوبة", "img": null, "points": ["الوقاية: تُختار لغة التقرير عند التقييم (عربية/إنجليزية/فرنسية) — أكّدها مع الأسرة كتابة قبل بدء الاستبيان.", "إن وقع الخطأ: لا تُسلّم التقرير ولا تترجمه بنفسك؛ فهو وثيقة رسمية تصدر بلغتها من مصدرها.", "التبليغ: لقطة من رأس التقرير تظهر الاسم واللغة الحالية + وصف فيه اللغة الصحيحة المطلوبة واسم الحالة."], "take": "الخلاصة: اللغة قرار لحظة التقييم لا لحظة التسليم — تثبيتها كتابة عادة صغيرة بثمن كبير.", "check": [], "task": "", "text": {"head": "3) تقرير بلغة غير المطلوبة", "body": "<ul><li>الوقاية أولًا: تُختار لغة التقرير عند التقييم (عربية/إنجليزية/فرنسية) — أكّدها مع الأسرة كتابة قبل بدء الاستبيان، فاللغة قرار لحظة التقييم لا لحظة التسليم.</li><li>إن وصلك تقرير بلغة غير التي طلبتها الأسرة: لا تُسلّمه ولا تحاول ترجمته بنفسك؛ التقرير وثيقة رسمية تصدر بلغتها من مصدرها.</li><li>بلّغ بالبروتوكول: لقطة من رأس التقرير تظهر الاسم واللغة الحالية + وصف فيه اللغة الصحيحة المطلوبة واسم الحالة.</li></ul>"}}, {"kind": "slide", "title": "حالة لم تُكمل الاستبيان", "img": null, "points": ["أولًا: استئناف الدخول بالكود نفسه من الجهاز نفسه — فالكود يُستهلك بالإرسال لا بمجرد الفتح.", "لا افتراضات: لا «ضاع التقييم» ولا وعد بحل فوري؛ سجّل عند أي بند توقفت الجلسة تقريبًا إن أمكن.", "التبليغ: لقطة آخر شاشة أو رسالة الخطأ + وصف فيه توقيت الانقطاع ونوع الاتصال والجهاز.", "وللأسرة جملة واحدة صادقة: «سجّلنا المشكلة بالطريقة الرسمية وننتظر المعالجة» — بلا مواعيد مخترعة."], "take": "الخلاصة: هدوؤك الموثّق عند العطل جزء من صورة عيادتك المهنية.", "check": [], "task": "", "text": {"head": "4) حالة لم تُكمل الاستبيان", "body": "<ul><li>أغلقت الأسرة الجلسة في المنتصف أو انقطع الاتصال: حاول أولًا استئناف الدخول بالكود نفسه من الجهاز نفسه — فالكود يُستهلك بالإرسال لا بمجرد الفتح.</li><li>إن لم يُستأنف: لا تفترض ضياع التقييم ولا تعد الأسرة بحل فوري؛ سجّل عند أي بند توقفت الجلسة تقريبًا إن عرفته الأسرة.</li><li>بلّغ بالبروتوكول: لقطة لآخر شاشة وصلتها الأسرة (أو رسالة الخطأ) + وصف فيه توقيت الانقطاع ونوع الاتصال والجهاز إن أمكن.</li><li>حتى يأتي الرد: أخبر الأسرة بجملة واحدة صادقة: «سجّلنا المشكلة بالطريقة الرسمية وننتظر المعالجة» — بلا مواعيد مخترعة.</li></ul>"}}, {"kind": "slide", "title": "مشاكل أخرى متكررة باختصار", "img": null, "points": ["صفحة لا تفتح أو ناقصة: متصفح ثانٍ واتصال آخر وتحديث الصفحة أولًا؛ إن تكررت عند أسرتين مختلفتين بلّغ فورًا.", "الخطة لا تفتح بكودها: تحقق من نوع الكود وسريان الاشتراك من ملف الحالة، ثم بلّغ عند الحاجة.", "«مجال اليوم» لا يوافق اليوم: يتبدل منتصف الليل بتوقيت المنظومة لا هاتفك — تحقق من اليوم والتاريخ أولًا."], "take": "الخلاصة: كل مشكلة إما تُحل محليًا بخطوة معروفة، أو تُبلَّغ كاملة من أول مرة — لا حالة ثالثة.", "check": [], "task": "", "text": {"head": "5) مشاكل أخرى متكررة باختصار", "body": "<ul><li>صفحة لا تُفتح أو تظهر ناقصة: جرّب متصفحًا ثانيًا واتصالًا آخر أولًا، وحدّث الصفحة؛ إن تكرر عندك وحدك فغالبًا محلي، وإن تكرر عند أسرتين مختلفتين بلّغ فورًا بالبروتوكول.</li><li>الخطة لا تُفتح بكود الخطة: تحقق من نوع الكود ومن أن اشتراك الحالة سارٍ (تاريخ البدء والمدة في ملفها عندك)، ثم بلّغ عند الحاجة.</li><li>«مجال اليوم» لا يوافق اليوم: المجال يتبدل منتصف الليل بتوقيت المنظومة لا بتوقيت هاتفك؛ تحقق من اليوم والتاريخ أولًا قبل اعتبارها مشكلة.</li></ul>"}}, {"kind": "slide", "title": "خلاصة الدرس — قائمة تحققك", "img": null, "points": [], "take": "", "check": ["أعرف البروتوكول: لقطة + وصف من 4 عناصر ← ماسنجر الصفحة.", "لا أبلّغ شفهيًا ولا أصف بلا لقطة أبدًا.", "أفحص الكود بالترتيب: صياغة، نوع وموضع، استهلاك سابق.", "أؤكد لغة التقرير قبل التقييم ولا أترجم تقريرًا بنفسي.", "أستأنف الجلسة غير المكتملة أولًا ثم أبلّغ موثّقًا."], "task": "مهمة عملية قبل الدرس التالي: أنشئ نموذج تبليغ جاهزًا بعناصر الوصف الأربعة فارغة، والتقط لقطة تجريبية لشاشة الأداة كما سترسلها لو وقعت مشكلة — ثم انتقل إلى اختبار المستوى الأول."}], "closing": [{"head": "خلاصة الدرس — قائمة تحققك كمختص شريك", "body": "<p>1. أعرف بروتوكول التبليغ: لقطة شاشة + وصف من 4 عناصر ← ماسنجر صفحة المؤسس.</p><p>2. لا أبلّغ شفهيًا ولا أصف بلا لقطة — أبدًا.</p><p>3. أفحص الكود المعطّل بالترتيب: الصياغة، النوع والموضع، الاستهلاك السابق.</p><p>4. أؤكد لغة التقرير مع الأسرة قبل التقييم، ولا أترجم تقريرًا بنفسي.</p><p>5. أتابع حالة الاستبيان غير المكتمل بالاستئناف أولًا ثم التبليغ الموثّق.</p>"}, {"head": "قبل أن تنتقل", "body": "<p>مهمة عملية أخيرة في هذا المستوى: أنشئ عندك نموذج تبليغ جاهز (ملف أو ملاحظة) فيه عناصر الوصف الأربعة فارغة تنتظر التعبئة، والتقط لقطة تجريبية لشاشة الأداة كما سترسلها لو حدثت مشكلة. ثم انتقل إلى اختبار المستوى الأول — عشرة أسئلة تقيس هذا المستوى كله.</p>"}], "scenario": {"q": "اتصلت بك أسرة هاتفيا: رفض الكود عندنا، بلا لقطة ولا تفاصيل. ما خطوتك الأولى؟", "opts": ["أبلغ المؤسس فورا بما سمعت", "أجرب أكوادا أخرى من رصيد العيادة حتى يعمل واحد", "أطلب اللقطة والوصف، وقبلهما ترشد الأسرة إلى الفحص المرتب: الصياغة، ثم النوع والموضع، ثم الاستهلاك السابق"], "c": 2, "ex": "ثلاث دقائق فحص مرتب توفر أغلب التبليغات، والتبليغ بلا لقطة لا يقبل أصلا."}, "quiz": [{"q": "أغلب أعطال الكود عند الفحص سببها:", "opts": ["عطل عام في المنصة", "حرف منسوخ خطأ، أو باب خاطئ، أو كود مستهلك أصلا", "بطء اتصال الأسرة"], "c": 1, "ex": "الكود المستهلك لا يعمل، وهذا سلوك صحيح في النظام لا عطل."}, {"q": "يستهلك كود التقييم:", "opts": ["بمجرد فتح صفحة الاستبيان", "عند استلام العيادة له", "بإكمال الاستبيان وإرساله"], "c": 2, "ex": "لهذا يمكن استئناف جلسة لم ترسل بعد بالكود نفسه من الجهاز نفسه."}, {"q": "الجملة الصادقة الواحدة للأسرة عند عطل موثق بانتظار المعالجة:", "opts": ["سنحل المشكلة هذه الليلة حتما", "سجلنا المشكلة بالطريقة الرسمية وننتظر المعالجة", "جربوا بأنفسكم غدا وستعمل"], "c": 1, "ex": "هدوؤك الموثق عند العطل جزء من صورة عيادتك المهنية، وبلا مواعيد مخترعة."}]}], "test": [{"q": "ما التعريف الأدق لأداة أوسع للبروفيل الحسي؟", "opts": ["أداة تشخيص للتوحد عبر استبيان إلكتروني", "منظومة تقيس البروفيل الحسي عبر تسعة مجالات، وتصدر تقريرًا ثم خطة أنشطة مبنية على النتيجة", "مكتبة أنشطة حسية جاهزة لكل الأعمار بلا تقييم", "بديل عن التقييم السريري الشامل للحالة"], "c": 1, "ex": "لأن الأداة سلسلة: قياس عبر تسعة مجالات ← تقرير ← خطة. وليست تشخيصًا (أ) ولا بديلًا سريريًا (د) ولا مكتبة بلا تقييم (ج) — الدرس 2 والدرس 9."}, {"q": "كم عدد بنود فئة 3 إلى 14 سنة، وما وضع فئة أكبر من 14 سنة؟", "opts": ["86 بندًا؛ وفئة أكبر من 14 عاملة كغيرها", "58 بندًا؛ وفئة أكبر من 14 قيد الاستكمال القريب", "86 بندًا؛ وفئة أكبر من 14 مجمّدة — عند طلب العيادات فقط", "48 بندًا؛ وفئة أكبر من 14 مخصصة للأولياء"], "c": 2, "ex": "86 بندًا رقم موثّق من مصدر الأداة لفئة 3-14؛ وفئة أكبر من 14 مجمّدة بقرار المؤسس (2026-10-24) ولا تُقدَّم إلا عند طلب العيادات — الدرس 3."}, {"q": "متعلم عمره الفعلي 10 سنوات، وقدّرت الأسرة «عمره العقلي» بنحو 6 سنوات. بأي فئة يُقيَّم؟", "opts": ["فئة أقل من 3 سنوات لأن بنودها أخف", "فئة 3 إلى 14 سنة، لأن المرجع هو العمر الفعلي", "تُجرَّب الفئتان ويُختار الأنسب من النتيجتين", "يُؤجَّل التقييم حتى يتضح العمر العقلي بدقة"], "c": 1, "ex": "اختيار الفئة قرار سريري مرجعه العمر الفعلي؛ وتبديل الفئات أو تجربتها يدمّر قابلية القراءة والمقارنة — الدرس 3."}, {"q": "ما الفرق الصحيح بين كود التقييم وكود الخطة؟", "opts": ["لا فرق؛ أي كود يعمل في أي باب", "كود التقييم مشترك بين الحالات، وكود الخطة فردي", "كود التقييم يفتح استبيانًا واحدًا ويُستهلك بإرساله، وكود الخطة يفتح خطة الأنشطة لحالة قيّمت ويرتبط بمدة اشتراكها", "كود الخطة يُستعمل مرة واحدة، وكود التقييم دائم"], "c": 2, "ex": "لكل كود وظيفة وباب ومدة: التقييم يُستهلك بالإرسال، والخطة ترتبط بالاشتراك؛ ولا توجد أكواد مشتركة أصلًا — الدرس 4."}, {"q": "ما قاعدة «السلوك المعتاد» عند إكمال الاستبيان؟", "opts": ["الإجابة عن سلوك المتعلم في أفضل أيامه لتشجيعه", "الإجابة عما يفعله عادة في الأسابيع الأخيرة، لا عن يوم استثنائي جيد أو سيئ", "الإجابة عن أحدث موقف نتذكره مهما كان", "الإجابة بالتقدير الأشدّ احتياطًا دائمًا"], "c": 1, "ex": "نص القاعدة كما تُشرح للأسرة قبل أول بند؛ اليوم الاستثنائي بنوعيه لا يمثل البروفيل — الدرس 5."}, {"q": "ماذا يحدث لحظة إرسال الاستبيان؟", "opts": ["تبقى الإجابات قابلة للتعديل لمدة 24 ساعة", "يُستهلك كود التقييم، وتُحسب النتيجة مجالًا مجالًا فيُبنى التقرير باسم المتعلم", "تصل النتيجة إلى الأسرة مباشرة بلا أي خطوة وسيطة", "يُفتح كود الخطة تلقائيًا لكل حالة"], "c": 1, "ex": "الإرسال نهائي ويستهلك الكود، والحساب مجالًا مجالًا، والتقرير يمرّ بمراجعة قبل التسليم فلا يصل مباشرة — الدرس 6."}, {"q": "أسرة تريد «التقرير فقط» دون خطة أنشطة. ما خيارها الصحيح وسعره؟", "opts": ["الاشتراك الشهري — 20$", "الاشتراك السنوي — 100$", "مجال اليوم — مجانًا", "البروفيل وحده — 10$"], "c": 3, "ex": "البروفيل وحده (10$) ينتهي عند التقرير والتوصيات؛ الشهري والسنوي خيارا خطة مدفوعة، والمجاني أنشطة عيّنة بلا تقرير — الدرس 7 والدرس 8."}, {"q": "ما الصياغة الصحيحة عن «مجال اليوم» المجاني؟", "opts": ["يعرض المجالات التسعة كلها بالتناوب اليومي", "يفتح مجالًا واحدًا يوميًا من سبعة مجالات؛ والانتباه والاجتماعي-العاطفي للمشتركين فقط، ولا يتضمن تقييمًا ولا تقريرًا", "هو تجربة كاملة للأداة لمدة أسبوع", "يغني الأسرة عن التقييم إن تابعته شهرًا كاملًا"], "c": 1, "ex": "الدورة سباعية (الجمعة إلى الخميس)، ومجالان محجوبان دائمًا عن المجاني، والمجاني عيّنة أنشطة لا قياس — الدرس 8."}, {"q": "أي مما يلي داخل ما تقيسه الأداة فعلًا؟", "opts": ["تشخيص التوحد من عدمه", "مستوى ذكاء المتعلم وتحصيله", "النمط الغالب في كل مجال من المجالات الحسية التسعة كما يظهر في السلوك اليومي", "سلامة السمع والبصر فحصًا طبيًا"], "c": 2, "ex": "هذا هو نطاق الأداة الكامل: وصف حسي سلوكي منظّم؛ التشخيص والذكاء والفحص الطبي كلها خارج نطاقها — الدرس 9."}, {"q": "وصلتك مشكلة: رُفض كود تقييم سليم الصياغة عند أسرة، بعد التحقق من نوعه وموضعه وأنه غير مستهلَك. ما التصرف المعتمد؟", "opts": ["الاتصال هاتفيًا وشرح المشكلة شفهيًا", "إرسال وصف مكتوب فقط دون صورة", "تجربة أكواد أخرى من رصيد العيادة حتى يعمل واحد", "لقطة شاشة لشاشة الرفض + وصف مكتوب (الحالة، نوع الكود، الخطوة، ما حدث) يُرسلان إلى ماسنجر صفحة المؤسس"], "c": 3, "ex": "بروتوكول التبليغ المعتمد: لقطة + وصف يُرسلان إلى ماسنجر صفحة المؤسس، ولا يُقبل تبليغ بلا لقطة؛ وتجربة أكواد أخرى (ج) تخلط سجلات الحالات — الدرس 10 والدرس 4."}]};
